<script>
/* ============================================================
 * 状态栏 · 环世界 · 原生JS + MVU
 * 参考"系统哥的末日"：多层宿主查找 + 内联变量兜底
 * ============================================================ */

/* 多层宿主：iframe 内 Mvu/getVariables 等挂在 window/parent/top */
var TH_HOSTS=[window,window.parent,window.top].filter(function(w,i,arr){return w&&arr.indexOf(w)===i});
function pickHostFn(name){
  if(typeof window[name]==='function')return function(){return window[name].apply(window,arguments)};
  for(var i=0;i<TH_HOSTS.length;i++){try{var h=TH_HOSTS[i];if(typeof h[name]==='function')return function(host,n){return function(){return host[n].apply(host,arguments)}}(h,name)}catch(e){}}
  return null;
}
function pickHostValue(name){
  if(window[name]!==undefined)return window[name];
  for(var i=0;i<TH_HOSTS.length;i++){try{if(TH_HOSTS[i][name]!==undefined)return TH_HOSTS[i][name]}catch(e){}}
  return undefined;
}
function getExt(n){return pickHostValue(n)||null}
function waitFor(n,timeout){timeout=timeout||5000;return new Promise(function(resolve){var start=Date.now();(function check(){var obj=getExt(n);if(obj)return resolve(obj);if(Date.now()-start>timeout)return resolve(null);setTimeout(check,100)})()})}
var _lodash=pickHostValue('_');

/* 从内联 JSON 宏读取 stat_data（首楼即可用，最强兜底） */
function parseEmbeddedStat(){
  var el=document.getElementById('mvu-stat-embed');
  if(!el)return null;
  var raw=(el.textContent||el.innerText||'').trim();
  if(!raw||raw.indexOf('format_message_variable')>=0)return null;
  try{
    var parsed=JSON.parse(raw);
    if(parsed&&typeof parsed==='object'){
      if(parsed.stat_data&&typeof parsed.stat_data==='object')return parsed.stat_data;
      return parsed;
    }
  }catch(e){}
  return null;
}
function hasData(o){return o&&typeof o==='object'&&!Array.isArray(o)&&Object.keys(o).length>0}

/* ============================================================
 * MVU 变量读取
 * 1. resolveMessageId() 4层策略精确定位当前消息 ID
 * 2. readStatData() 同步调用 Mvu.getMvuData(getMessageOption())
 * 3. bridge 机制：postMessage 跨框架请求数据作为异步兜底
 * 4. waitForReadableStat() 在 render 前轮询等待数据就绪
 * ============================================================ */
function getMvu(){return pickHostValue('Mvu')||window.Mvu||null}
function parseMesId(v){var n=parseInt(v,10);return Number.isFinite(n)&&n>=0?n:-1}
function resolveMessageIdFromIframeName(){
  var fn=pickHostFn('getIframeName');
  if(!fn)return -1;
  try{
    var name=String(fn()||'');
    var m=/^TH-message--(\d+)--/.exec(name);
    if(m)return parseMesId(m[1]);
  }catch(e){}
  return -1;
}
function resolveMessageIdFromDom(){
  try{
    var frame=window.frameElement;
    if(frame&&frame.closest){
      var mes=frame.closest('.mes');
      if(mes){var id=parseMesId(mes.getAttribute('mesid'));if(id>=0)return id}
    }
    var el=frame;
    while(el){
      if(el.classList&&el.classList.contains('mes')){
        var id2=parseMesId(el.getAttribute('mesid'));
        if(id2>=0)return id2;
      }
      el=el.parentElement;
    }
    for(var i=0;i<TH_HOSTS.length;i++){
      try{
        var host=TH_HOSTS[i];
        var host$=host.$||host.jQuery;
        if(!host$||!frame)continue;
        var $mes=host$(frame).closest('.mes');
        if($mes&&$mes.length){
          var id3=parseMesId($mes.attr('mesid'));
          if(id3>=0)return id3;
        }
      }catch(e){}
    }
  }catch(e){}
  return -1;
}
function resolveMessageId(){
  var fromDom=resolveMessageIdFromDom();
  if(fromDom>=0)return fromDom;
  var fromName=resolveMessageIdFromIframeName();
  if(fromName>=0)return fromName;
  if(typeof window.message_id==='number'&&Number.isFinite(window.message_id)&&window.message_id>=0){
    return window.message_id;
  }
  var fn=pickHostFn('getCurrentMessageId');
  if(fn){
    try{
      var id=fn();
      if(typeof id==='number'&&Number.isFinite(id)&&id>=0)return id;
    }catch(e){}
  }
  return -1;
}
function getMessageOption(){
  var messageId=resolveMessageId();
  return {type:'message',message_id:messageId>=0?messageId:'latest'};
}
function hasMeaningfulStatData(stat){
  return stat&&typeof stat==='object'&&!Array.isArray(stat)&&Object.keys(stat).length>0;
}
function pickStatData(source){
  if(!source||typeof source!=='object')return null;
  var stat=source.stat_data;
  if(_lodash&&typeof _lodash.get==='function'){
    try{stat=_lodash.get(source,'stat_data')}catch(e){}
  }
  return hasMeaningfulStatData(stat)?stat:null;
}
/* bridge 缓存 */
var cachedStatFromBridge=null;
var cachedBridgeMessageId=-1;
/* 同步读取 stat_data：内联JSON(首楼兜底) -> MVU API -> getVariables -> bridge缓存 -> getAllVariables -> DEFAULT_STAT */
function readStatData(){
  /* 0. 内联 JSON 宏 (首楼兜底,首楼 initvar 初始值) - 同级生2模式，优先读取 */
  var embedded=parseEmbeddedStat();
  if(embedded)return deepMergeStat(DEFAULT_STAT,embedded);
  var mesId=resolveMessageId();
  var opt=getMessageOption();
  /* 1. MVU API (含 message_id) */
  var Mvu=getMvu();
  try{
    if(Mvu&&typeof Mvu.getMvuData==='function'){
      var stat=pickStatData(Mvu.getMvuData(opt));
      if(stat)return deepMergeStat(DEFAULT_STAT,stat);
    }
  }catch(e){}
  /* 2. getVariables (含 message_id) */
  try{
    var getVariablesFn=pickHostFn('getVariables');
    if(getVariablesFn){var s2=pickStatData(getVariablesFn(opt));if(s2)return deepMergeStat(DEFAULT_STAT,s2)}
  }catch(e){}
  /* 3. bridge 缓存 (跨 iframe 桥接) */
  if(cachedStatFromBridge&&hasMeaningfulStatData(cachedStatFromBridge)&&
     (cachedBridgeMessageId<0||mesId<0||cachedBridgeMessageId===mesId)){
    return deepMergeStat(DEFAULT_STAT,cachedStatFromBridge);
  }
  /* 4. getAllVariables (最后宿主兜底) */
  try{
    var getAllVariablesFn=pickHostFn('getAllVariables');
    if(getAllVariablesFn){var s3=pickStatData(getAllVariablesFn());if(s3)return deepMergeStat(DEFAULT_STAT,s3)}
  }catch(e){}
  /* 5. DEFAULT_STAT 常量兜底 */
  return deepMergeStat(DEFAULT_STAT,{});
}
/* bridge 请求 */
function requestStatFromBridge(){
  var mesId=resolveMessageId();
  var payload={type:'rw-mvu-stat-request',messageId:mesId};
  for(var i=0;i<TH_HOSTS.length;i++){
    try{TH_HOSTS[i].postMessage(payload,'*')}catch(e){}
  }
}
/* 轮询等待可读 stat */
function waitForReadableStat(timeoutMs){
  timeoutMs=timeoutMs||8000;
  var started=Date.now();
  return new Promise(function(resolve){
    (function check(){
      var stat=readStatData();
      if(hasMeaningfulStatData(stat))return resolve(stat);
      if(Date.now()-started>=timeoutMs)return resolve(readStatData());
      requestStatFromBridge();
      setTimeout(check,180);
    })();
  });
}

/* ============================================================
 * 首楼默认数据（与 initvar.yaml 对齐；姓名/类型字段含 UI 显示回退值）
