/* ============================================================
 * 工具函数
 * ============================================================ */
function esc(s){
  return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}
function num(v,d){v=parseFloat(v);d=(d===undefined)?0:d;return isNaN(v)?d:v}
function pct(v,max){v=num(v,0);max=num(max,100);return Math.max(0,Math.min(100,max>0?(v/max)*100:0))}
function barClass4(v){v=parseInt(v)||0;if(v>=80)return'g';if(v>=60)return'y';if(v>=30)return'o';return'r'}
function barClassInv(v){v=parseInt(v)||0;if(v>=80)return'r';if(v>=60)return'o';if(v>=30)return'y';return'g'}
function barClass20(v){v=parseInt(v)||0;var p=(v/20)*100;return barClass4(p)}
function mvuObj(key){return(State.mvu&&State.mvu[key])||{}}

/* 飞船进度（0-100）：反应堆3 + AI核心1 + 结构1 = 满分5 */
function shipProgress(col){
  var r=num(col.飞船反应堆,0);
  var ai=num(col.飞船AI核心,0);
  var st=num(col.飞船结构,0);
  var total=r+ai+st;
  return pct(total,5);
}
/* 温度颜色 */
function tempColor(t){
  t=num(t,20);
  if(t<0)return'blue';
  if(t<15)return'blue';
  if(t<=30)return'safe';
  if(t<=40)return'warn';
  return'danger';
}
/* 天气图标 */
function weatherIcon(w){
  w=w||'晴';
  if(w.indexOf('暴风雪')>=0)return'⚠';
  if(w.indexOf('雪')>=0)return'❄';
  if(w.indexOf('大雨')>=0)return'☔';
  if(w.indexOf('雨')>=0)return'💧';
  if(w.indexOf('雾')>=0)return'🌫';
  if(w.indexOf('沙尘暴')>=0)return'💨';
  if(w.indexOf('阴')>=0)return'☁';
  return'☀';
}
/* 季节图标 */
function seasonIcon(s){
  s=s||'春';
  if(s==='春')return'🍃';
  if(s==='夏')return'☀';
  if(s==='秋')return'🌳';
  if(s==='冬')return'❄';
  return'🍃';
}
/* 时段图标 */
function timeIcon(ts){
  ts=ts||'清晨';
  if(ts.indexOf('深夜')>=0||ts.indexOf('夜晚')>=0)return'🌙';
  if(ts.indexOf('傍晚')>=0)return'🌙';
  if(ts.indexOf('清晨')>=0||ts.indexOf('上午')>=0)return'☀';
  return'☀';
}
/* 警戒等级颜色 */
function alertColor(v){
  v=parseInt(v)||0;
  if(v>=80)return'danger';
  if(v>=60)return'warn';
  if(v>=30)return'accent';
  return'safe';
}
/* NSFW JSON 字段解析 */
function parseNSFW(s){
  if(!s||s==='{}'||s==='')return'';
  try{
    var obj=JSON.parse(s);
    if(!obj||typeof obj!=='object')return'';
    var keys=Object.keys(obj);
    if(!keys.length)return'';
    var parts=[];
    for(var i=0;i<keys.length;i++){
      parts.push(keys[i]+': '+obj[keys[i]]);
    }
    return parts.join('，');
  }catch(e){return'';}
}

