function getColonistList(){
  var out=[];
  for(var i=0;i<COLONIST_KEYS.length;i++){
    var key=COLONIST_KEYS[i];
    var c=mvuObj(key);
    var name=c.姓名||COLONIST_LABELS[i];
    var mood=num(c.心情,50);
    var hunger=num(c.饱腹,80);
    var fatigue=num(c.疲劳,20);
    var fun=num(c.娱乐,50);
    /* 判断倒下：任意身体部位HP<=0 */
    var downed=false;
    for(var j=0;j<BODY_PARTS.length;j++){
      if(num(c[BODY_PARTS[j]],100)<=0){downed=true;break}
    }
    out.push({key:key,idx:i,name:name,mood:mood,hunger:hunger,fatigue:fatigue,fun:fun,downed:downed,data:c});
  }
  return out;
}
