/* ============================================================
 * 主渲染
 * ============================================================ */
function render(){
  var loadingEl=document.getElementById('sb-loading');
  var bodyEl=document.getElementById('sb-body');
  if(!bodyEl)return;
  if(State.loading){loadingEl.style.display='';bodyEl.style.display='none';return}
  loadingEl.style.display='none';
  bodyEl.style.display='';
  var html=renderSystemBar()+renderColonists()+renderColony()+renderAnimals()+renderFactions()+renderEvent();
  if(State.error){html+='<div class="error"><span class="ic">⚠</span> '+esc(State.error)+'</div>'}
  bodyEl.innerHTML=html;
  renderModal();
}

/* ============================================================
 * refresh
 * ============================================================ */
function refresh(){
  if(State._refreshing)return;
  State._refreshing=true;State.refreshing=true;
  try{
    var stat=readStatData();
    if(hasData(stat)){State.mvu=stat;State.loading=false}
    render();
  }catch(e){State.loading=false;State.error=String(e);render()}
  waitForReadableStat(8000).then(function(realStat){
    try{
      if(hasData(realStat)){State.mvu=realStat;State.loading=false}
      State.loading=false;State._refreshing=false;State.refreshing=false;
      render();requestStatFromBridge();
    }catch(e){State.loading=false;State._refreshing=false;State.refreshing=false;State.error=String(e);render()}
  });
}

/* ============================================================
 * 事件委托 + 初始化
 * ============================================================ */
function bindEvents(){
  var root=document.getElementById('sb-root');
  root.addEventListener('toggle',function(e){
    var t=e.target;
    if(t&&t.tagName==='DETAILS'){
      var key=t.getAttribute('data-key');
      if(key){State.expanded[key]=t.hasAttribute('open')}
    }
  },true);
  root.addEventListener('click',function(e){
    var t=e.target.closest('[data-act]');
    if(!t)return;
    var act=t.getAttribute('data-act');
    if(act==='refresh'){refresh()}
    else if(act==='colonist'){
      var idx=parseInt(t.getAttribute('data-idx'));
      var list=window._sbColonists||[];
      State.selectedColonist=list[idx]||null;
      State.nsfwOpen=false;
      renderModal();
    }
  });
  var modal=document.getElementById('sb-modal');
  modal.addEventListener('click',function(e){
    var t=e.target.closest('[data-act]');
    if(!t)return;
    var act=t.getAttribute('data-act');
    if(act==='modal-close'){State.selectedColonist=null;renderModal()}
    else if(act==='nsfw-toggle'){State.nsfwOpen=!State.nsfwOpen;renderModal()}
  });
}

function init(){
  bindEvents();
  var autoRefresh=function(){setTimeout(refresh,800)};
  try{
    if(typeof eventOn==='function'){
      eventOn('GENERATION_ENDED',autoRefresh);
      eventOn('MESSAGE_EDITED',autoRefresh);
    }
  }catch(e){}
  try{
    var Mvu=getMvu();
    if(Mvu&&Mvu.events&&Mvu.events.VARIABLE_UPDATE_ENDED&&typeof eventOn==='function'){
      eventOn(Mvu.events.VARIABLE_UPDATE_ENDED,autoRefresh);
    }
  }catch(e){}
  try{
    var tavernEvents=pickHostValue('tavern_events');
    if(tavernEvents&&typeof eventOn==='function'){
      if(tavernEvents.MESSAGE_UPDATED)eventOn(tavernEvents.MESSAGE_UPDATED,autoRefresh);
      if(tavernEvents.MESSAGE_RECEIVED)eventOn(tavernEvents.MESSAGE_RECEIVED,autoRefresh);
    }
  }catch(e){}
  /* mag_variable_update_ended 事件 */
  try{
    if(typeof eventOn==='function'){
      eventOn('mag_variable_update_ended',autoRefresh);
    }
  }catch(e){}
  window.addEventListener('message',function(e){
    try{
      var data=e.data;
      if(data&&data.type==='rw-mvu-stat-data'&&data.stat_data){
        var mesId=resolveMessageId();
        if(mesId>=0&&typeof data.messageId==='number'&&data.messageId>=0&&data.messageId!==mesId)return;
        if(hasMeaningfulStatData(data.stat_data)){
          cachedStatFromBridge=data.stat_data;
          cachedBridgeMessageId=typeof data.messageId==='number'?data.messageId:mesId;
          State.mvu=deepMergeStat(DEFAULT_STAT,data.stat_data);
          State.loading=false;
          render();
        }
        return;
      }
      var t=(data&&data.type)||data||'';
      if(typeof t==='string'&&(t.indexOf('generation_ended')>=0||t.indexOf('message_edit')>=0||t.indexOf('variable_update')>=0))autoRefresh();
    }catch(x){}
  });
  var embedded=parseEmbeddedStat();
  if(embedded){
    cachedStatFromBridge=embedded;
    cachedBridgeMessageId=resolveMessageId();
  }
  requestStatFromBridge();
  refresh();
  /* 异步等待 Mvu 初始化完成后再刷新一次（满足 dynamic_js 验证要求，不阻塞首楼显示） */
  try{
    var waitFn=pickHostFn('waitGlobalInitialized');
    if(typeof waitFn==='function'){
      Promise.resolve(waitFn('Mvu')).then(function(){ setTimeout(refresh, 200); }).catch(function(){});
    }else{
      waitFor('Mvu', 5000).then(function(mvu){ if(mvu) setTimeout(refresh, 200); });
    }
  }catch(e){}
}

if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init)}
else{init()}
</script>
</body>
</html>
