var newFatigue = Math.max(0, Math.min(100, fatigue + 5));
var newJoy = Math.max(0, Math.min(100, joy - 3));

function _satietyMod(s) {
  if (s <= 0) { return { mood: -25, work: 0, health: -10 }; }
  if (s < 10) { return { mood: -20, work: 0.7, health: -5 }; }
  if (s < 30) { return { mood: -12, work: 0.85, health: 0 }; }
  if (s < 50) { return { mood: -5, work: 0.95, health: 0 }; }
  if (s <= 80) { return { mood: 3, work: 1.0, health: 0 }; }
  return { mood: 8, work: 1.0, health: 0 };
}

function _fatigueMod(f) {
  if (f >= 100) { return { mood: -25, work: 0, note: '强制休息' }; }
  if (f > 80) { return { mood: -15, work: 0.7, note: '-' }; }
  if (f > 60) { return { mood: -8, work: 0.9, note: '-' }; }
  if (f >= 41) { return { mood: -3, work: 1.0, note: '-' }; }
  return { mood: 5, work: 1.0, note: '可全效工作' };
}

/* 公式以DDL骰子引擎为准，禁止本地修改 */
function _moodMod(m) {
  if (m > 85) { return { work: 1.15, effect: '灵感触发5%/轮' }; }
  if (m >= 60) { return { work: 1.0, effect: '偶发灵感1%/轮' }; }
  if (m >= 30) { return { work: 0.7, effect: '无灵感' }; }
  if (m >= 20) { return { work: 0.8, effect: '消极怠工10%/轮' }; }
  if (m >= 15) { return { work: 0.7, effect: '30%轻度崩溃' }; }
  if (m >= 10) { return { work: 0.5, effect: '70%中度崩溃' }; }
  return { work: 0, effect: '必然重度崩溃' };
}

function _tempMod(t) {
  if (t < 0) { return { mood: -10, health: -3 }; }
  if (t < 10) { return { mood: -6, health: -1 }; }
  if (t < 16) { return { mood: -2, health: 0 }; }
  if (t <= 26) { return { mood: 2, health: 0 }; }
  if (t <= 35) { return { mood: -3, health: 0 }; }
  if (t <= 50) { return { mood: -6, health: -1 }; }
  return { mood: -10, health: -3 };
}

function _joyMod(j) {
  if (j > 80) { return { mood: 5, work: 1.0 }; }
  if (j > 50) { return { mood: 2, work: 1.0 }; }
  if (j >= 30) { return { mood: -3, work: 0.95 }; }
  return { mood: -8, work: 0.95 };
}

function _beautyMod(b) {
  if (b >= 90) { return 8; }
  if (b >= 70) { return 5; }
  if (b >= 50) { return 2; }
  if (b >= 30) { return 0; }
  if (b >= 15) { return -3; }
  if (b >= 5) { return -8; }
  return -15;
}

function _comfortMod(c) {
  if (c >= 90) { return 10; }
  if (c >= 70) { return 5; }
  if (c >= 40) { return 3; }
  if (c >= 10) { return -5; }
  return -12;
}

function _spaceMod(crowd) {
  if (crowd === '宽敞') { return 5; }
  if (crowd === '普通') { return 0; }
  if (crowd === '拥挤') { return -5; }
  return -10;
}

function _socialMod(status) {
  if (status === '有伴侣') { return 10; }
  if (status === '有密友') { return 5; }
  if (status === '独居>3天') { return -5; }
  if (status === '长期孤立>7天') { return -15; }
  return 0;
}

function _checkBreakdown(m, seed) {
  if (m < 10) {
    return { severity: '重度', behavior: ['攻击同伴','自伤','纵火','暴食'], duration: 12 };
  }
  if (m < 15) {
    var roll = _lcgRoll(seed, 1, 100)[0];
    if (roll <= 70) {
      return { severity: '中度', behavior: ['破坏物品','骂人','拒绝工作'], duration: 8 };
    }
    return { severity: '重度', behavior: ['攻击同伴','自伤','纵火','暴食'], duration: 12 };
  }
  if (m < 20) {
    var roll2 = _lcgRoll(seed, 1, 100)[0];
    if (roll2 <= 30) {
      return { severity: '轻度', behavior: ['游荡','发呆','哭立'], duration: 4 };
    }
    return { severity: '无', behavior: [], duration: 0 };
  }
  return { severity: '无', behavior: [], duration: 0 };
}

var satMod = _satietyMod(newSatiety);
var fatMod = _fatigueMod(newFatigue);
var joyMod = _joyMod(newJoy);
var tempMod = _tempMod(newTemp);
var beautyModVal = _beautyMod(beauty);
var comfortModVal = _comfortMod(comfort);
var spaceModVal = _spaceMod('普通');
var socialModVal = _socialMod('有密友');

var moodBase = 50;
var moodTotal = moodBase + satMod.mood + fatMod.mood + joyMod.mood + tempMod.mood + beautyModVal + comfortModVal + spaceModVal + socialModVal;
var finalMood = Math.max(0, Math.min(100, moodTotal));

if (blackout) { finalMood = Math.max(0, finalMood - 5); }

var moodInfo = _moodMod(finalMood);
var breakdown = _checkBreakdown(finalMood, 'breakdown_' + newGameDay + '_' + nextSlot);

var workEfficiency = satMod.work * fatMod.work * joyMod.work * moodInfo.work;
var healthDelta = satMod.health + tempMod.health;
var totalMoodChange = mood - finalMood;
_%>
