<%_
var raidCooldown = Number(getvar('stat_data.殖民地.袭击冷却', { scope: 'local', defaults: 96 })) || 96;
var threatPoints = Number(getvar('stat_data.殖民地.威胁点数', { scope: 'local', defaults: 0 })) || 0;
