var storyteller = getvar('stat_data.殖民地.故事讲述者', { scope: 'local', defaults: '卡桑德拉' }) || '卡桑德拉';
var phase = getvar('stat_data.殖民地.阶段', { scope: 'local', defaults: '拓荒期' }) || '拓荒期';
var lastRaidDay = Number(getvar('stat_data.事件计时器.上次袭击日', { scope: 'local', defaults: 0 })) || 0;

var minInterval;
if (storyteller === '菲比') { minInterval = 2; }
else if (storyteller === '兰迪') { minInterval = 1; }
else { minInterval = 3; }

var daysSinceLastRaid = gameDay - lastRaidDay;
var cooldownReady = (raidCooldown <= 0);
var intervalMet = (daysSinceLastRaid >= minInterval);
var willTrigger = cooldownReady && intervalMet;

var raidIntensity = 0;
var decayFactor = 0;
var enemySuggestion = '无';
if (willTrigger) {
  decayFactor = Math.round((0.8 + 0.4 * daysSinceLastRaid / 10) * 100) / 100;
  raidIntensity = Math.round(threatPoints * decayFactor * 100) / 100;
  if (phase === '拓荒期') {
    if (raidIntensity < 50) { enemySuggestion = '兔群 / 单只疯兽'; }
    else { enemySuggestion = '小型掠夺者团伙 (3-5人)'; }
  } else if (phase === '发展期') {
    if (raidIntensity < 100) { enemySuggestion = '掠夺者团伙 (5-8人)'; }
    else { enemySuggestion = '部族袭击队 (8-12人)'; }
  } else if (phase === '繁荣期') {
    if (raidIntensity < 200) { enemySuggestion = '精锐佣兵团 (10-15人)'; }
    else { enemySuggestion = '机械族集群 / 大型围攻 (15+人)'; }
  } else {
    enemySuggestion = '机械族终末部队 / 全方位围攻 (20+人)';
  }
}
