/* 科技树10级定义 */
function _techTree() {
  return [
    { level: 1, name: '基础研究', cost: 400, req: 0, note: '基础生存科技' },
    { level: 2, name: '电力', cost: 600, req: 0, note: '解锁发电与储能' },
    { level: 3, name: '居住', cost: 500, req: 0, note: '改善居住条件' },
