var p2Plant = Number(getvar('stat_data.殖民者_2.种植', { scope: 'local', defaults: 5 })) || 5;

var temperature = Number(getvar('stat_data.殖民地.温度', { scope: 'local', defaults: 20 })) || 20;
var season = getvar('stat_data.殖民地.季节', { scope: 'local', defaults: '春' }) || '春';
var timeSlot = getvar('stat_data.殖民地.时段', { scope: 'local', defaults: '清晨' }) || '清晨';
var biome = getvar('stat_data.殖民地.biome', { scope: 'local', defaults: '温带森林' }) || '温带森林';

var a1Type = getvar('stat_data.动物_1.类型', { scope: 'local', defaults: '' }) || '';
var a1Name = getvar('stat_data.动物_1.姓名', { scope: 'local', defaults: '' }) || '';
var a1Gender = getvar('stat_data.动物_1.性别', { scope: 'local', defaults: '雄' }) || '雄';
var a1Age = Number(getvar('stat_data.动物_1.年龄', { scope: 'local', defaults: 1 })) || 1;
var a1Health = Number(getvar('stat_data.动物_1.健康', { scope: 'local', defaults: 100 })) || 100;
var a1Mood = Number(getvar('stat_data.动物_1.心情', { scope: 'local', defaults: 50 })) || 50;
var a1Tame = Number(getvar('stat_data.动物_1.驯服度', { scope: 'local', defaults: 100 })) || 100;
var a1Train = Number(getvar('stat_data.动物_1.训练等级', { scope: 'local', defaults: 0 })) || 0;
var a1Product = getvar('stat_data.动物_1.产物计时', { scope: 'local', defaults: '0' }) || '0';

var FERTILITY_DB = {
  '贫瘠': 0.6,
  '普通': 0.8,
  '肥沃': 1.2,
  '施肥': 1.2,
  '水培': 1.5
};

var LIGHT_DB = {
  '室外白天': 1.0,
  '夜间': 0.0,
  '温室太阳灯': 1.0,
  '温室无灯': 0.5,
  '火山冬天': 0.2
};

/* 公式以DDL骰子引擎为准，禁止本地修改 */
function _cropGrowth(baseSpeed, plantSkill, temp, fertility, light, water) {
  var base = Number(baseSpeed) || 1;
  var skl = Number(plantSkill) || 0;
  var t = Number(temp) || 20;
  var fert = FERTILITY_DB[fertility] != null ? FERTILITY_DB[fertility] : 0.8;
  var lt = LIGHT_DB[light] != null ? LIGHT_DB[light] : 1.0;
  var w = Number(water) || 1.0;
  var skillMod = (1 + skl * 0.06) * (1 + skl * 0.02);
  var tempMod = 1.0;
  if (t >= 16 && t <= 26) { tempMod = 1.0; }
  else if ((t >= 10 && t <= 15) || (t >= 27 && t <= 35)) { tempMod = 0.7; }
  else { tempMod = 0.0; }
  var result = base * skillMod * tempMod * fert * lt * w;
  return Math.round(result * 100) / 100;
}

function _tempMod(temp) {
  var t = Number(temp) || 20;
  if (t >= 16 && t <= 26) { return 1.0; }
  if ((t >= 10 && t <= 15) || (t >= 27 && t <= 35)) { return 0.7; }
  return 0.0;
}

function _tameChance(animalSkill, seed, difficulty) {
  var val = (Number(animalSkill) || 0) * 5;
  var r = _check(val, seed, difficulty);
  return { 检定值: val, 骰值: r.roll, 阈值: r.threshold, 结果: r.result };
}

function _trainTime(baseTime, animalSkill) {
  var base = Number(baseTime) || 1;
  var skl = Number(animalSkill) || 0;
  var mod = Math.max(0.3, 1 - skl * 0.03);
  return Math.round(base * mod * 100) / 100;
}

function _trainChance(animalSkill, seed) {
  var val = (Number(animalSkill) || 0) * 4;
  var r = _check(val, seed, '普通');
  return { 检定值: val, 骰值: r.roll, 阈值: r.threshold, 结果: r.result };
}

function _breedCheck(foodPct, mood, hasMale, hasFemale) {
  var food = Number(foodPct) || 0;
  var m = Number(mood) || 0;
  if (!hasMale || !hasFemale) { return { 可繁殖: false, 原因: '需1公1母' }; }
  if (food <= 80) { return { 可繁殖: false, 原因: '食物满足度需>80%' }; }
  if (m < 40) { return { 可繁殖: false, 原因: '心情需>40' }; }
  return { 可繁殖: true, 原因: '条件满足', 妊娠食量: 1.5, 哺乳加成: 0.5 };
}

function _animalMood(foodPct, hasShelter, hasCompanion, trainLevel) {
  var food = Number(foodPct) || 0;
  var base = 50;
  var foodBonus = food >= 80 ? 20 : (food >= 50 ? 10 : 0);
  var shelterBonus = hasShelter ? 10 : 0;
  var compBonus = hasCompanion ? 10 : 0;
  var trainBonus = (Number(trainLevel) || 0) * 5;
  var mood = base + foodBonus + shelterBonus + compBonus + trainBonus;
  var status = '正常';
  if (mood < 15) { status = '暴走'; }
  else if (mood < 30) { status = '可能逃跑'; }
  return { 心情: mood, 状态: status };
}

function _productCollect(animalType, animalSkill, lastProductDay) {
  var skl = Number(animalSkill) || 0;
  var mod = 1 + skl * 0.05;
  var days = Number(lastProductDay) || 0;
  var ready = days >= 1;
  return { 产物修正: Math.round(mod * 100) / 100, 可收集: ready };
}

var growthSample = _cropGrowth(1.0, p1Plant, temperature, '肥沃', '室外白天', 1.0);
var tempModVal = _tempMod(temperature);
var tameSample = _tameChance(p1Animal, 'tame_demo', '普通');
var trainSample = _trainChance(p1Animal, 'train_demo');
var moodSample = _animalMood(85, true, true, a1Train);
_%>
<种植畜牧系统就绪>
[当前种植状态]
温度: <%= temperature %>°C (温度修正:<%= tempModVal %>)
季节: <%= season %> 时段: <%= timeSlot %>
生态群落: <%= biome %>

殖民者技能:
1. <%= p1Name %> - 种植:<%= p1Plant %> 畜牧:<%= p1Animal %>
2. <%= p2Name %> - 种植:<%= p2Plant %>

动物状态:
1. <%= a1Type %>(<%= a1Name %>) 性别:<%= a1Gender %> 年龄:<%= a1Age %>
   健康:<%= a1Health %> 心情:<%= a1Mood %> 驯服度:<%= a1Tame %> 训练等级:<%= a1Train %> 产物计时:<%= a1Product %>

[种植规则]
生长公式: 实际速度 = 基础速度 × 技能修正((1+种植×0.06)×(1+种植×0.02)) × 温度修正 × 肥力修正 × 光照修正 × 水分修正
  示例: <%= p1Name %>种植<%= p1Plant %>,温度<%= temperature %>°C,肥沃,室外白天 → 生长速度×<%= growthSample %>

温度修正:
  16-26°C: 1.0 (最佳)
  10-15°C或27-35°C: 0.7 (可生长非最佳)
  其他: 0.0 (无法生长)

肥力修正:
  贫瘠: ×0.6
  普通: ×0.8
  肥沃: ×1.2
  施肥: ×1.2
  水培: ×1.5

光照修正:
  室外白天: ×1.0
  夜间: ×0.0
  温室太阳灯: ×1.0
  温室无灯: ×0.5
  火山冬天: ×0.2

水分修正: 根据灌溉情况0.0-1.5
配方查询: 查CROP_DB获取作物基础生长速度/生长天数/产量/温度区间

[畜牧规则]
驯服公式: _check(畜牧技能×5, seed, 难度)
  难度等级: 极易/易/中/难/极难
  极难(6-7级难度): 阈值=检定值÷5
  示例: <%= p1Name %>畜牧<%= p1Animal %> → 阈值:<%= tameSample.阈值 %> 结果:<%= tameSample.结果 %>

训练公式:
  每级时间 = 基础时间 × (1 - 畜牧×0.03), 最低0.3
  训练率 = _check(畜牧×4, seed, '普通')
  示例: <%= p1Name %>畜牧<%= p1Animal %> → 训练检定阈值:<%= trainSample.阈值 %> 结果:<%= trainSample.结果 %>

繁殖条件:
  必要: 1公1母 + 食物满足度>80% + 心情>40
  妊娠期间: 食量×1.5
  产后哺乳: +0.5N/天

动物心情:
  基础: 50
  食物(+20 if >80% / +10 if >50%)
  住所(+10)
  陪伴(+10)
  训练度(每级+5)
  心情<30: 可能逃跑
  心情<15: 暴走
  示例: 食物85%+有住所+有陪伴+训练<%= a1Train %>级 → 心情:<%= moodSample.心情 %> 状态:<%= moodSample.状态 %>

产物收集:
  产出修正: 1 + 畜牧×0.05
  查ANIMAL_DB获取产物类型/周期/基础产量

[行为校验要求]
种植/畜牧行为必须输出行为校验块:
  行为类型: 播种/浇水/施肥/收获/驯服/训练/喂食/挤奶/剪毛/屠宰/繁殖
  执行者: 殖民者姓名
  技能等级: 种植或畜牧技能值
  目标: 作物名称(查CROP_DB)或动物类型(查ANIMAL_DB)
  生长计算: _cropGrowth()结果(种植类)
  驯服检定: _tameChance()结果(驯服类)
  训练检定: _trainChance()结果(训练类)
  繁殖检查: _breedCheck()结果(繁殖类)
  心情判定: _animalMood()结果(动物相关)
  产物收集: _productCollect()结果(产物类)
  温度影响: 当前温度修正系数
</种植畜牧系统就绪>

@@generate_before
<%_
var p1Name = getvar('stat_data.殖民者_主角.姓名', { scope: 'local', defaults: '' }) || '';
var p1Cook = Number(getvar('stat_data.殖民者_主角.厨艺', { scope: 'local', defaults: 5 })) || 5;
var p1Age = Number(getvar('stat_data.殖民者_主角.年龄', { scope: 'local', defaults: 25 })) || 25;
var p1Pregnant = Number(getvar('stat_data.殖民者_主角.怀孕状态', { scope: 'local', defaults: 0 })) || 0;

var p2Name = getvar('stat_data.殖民者_2.姓名', { scope: 'local', defaults: '' }) || '';
var p2Cook = Number(getvar('stat_data.殖民者_2.厨艺', { scope: 'local', defaults: 5 })) || 5;

var temperature = Number(getvar('stat_data.殖民地.温度', { scope: 'local', defaults: 20 })) || 20;
var season = getvar('stat_data.殖民地.季节', { scope: 'local', defaults: '春' }) || '春';
var timeSlot = getvar('stat_data.殖民地.时段', { scope: 'local', defaults: '清晨' }) || '清晨';
var silver = Number(getvar('stat_data.殖民地.银两', { scope: 'local', defaults: 800 })) || 800;

var ROT_TEMP_DB = {
  '极寒': 0.0,
  '冰冻': 0.1,
  '冷藏': 0.3,
  '凉爽': 0.5,
  '常温': 1.0,
  '温暖': 1.5,
  '炎热': 2.5,
  '酷热': 4.0
};

function _tempRotCoeff(temp) {
  var t = Number(temp) || 20;
  if (t < -5) { return 0.0; }
  if (t < 0) { return 0.1; }
  if (t < 5) { return 0.3; }
  if (t < 10) { return 0.5; }
  if (t < 20) { return 1.0; }
  if (t < 30) { return 1.5; }
  if (t < 40) { return 2.5; }
  return 4.0;
}

/* 公式以DDL骰子引擎为准，禁止本地修改 */
function _cookTime(baseTime, cookSkill) {
  var skl = Number(cookSkill) || 0;
  var base = Number(baseTime) || 1;
  return Math.round(base / (1 + skl * 0.1) * 100) / 100;
}

function _cookQuality(cookSkill, seed) {
  var skl = Number(cookSkill) || 0;
  var quality = '普通';
  if (skl >= 18) { quality = '传奇'; }
  else if (skl >= 13) { quality = '大师'; }
  else if (skl >= 8) { quality = '优秀'; }
  else if (skl >= 4) { quality = '良好'; }
  else {
    var failRate = Math.max(0, 40 - skl * 2);
    var r = _check(skl * 5, seed, '普通');
    if (r.result === '失败' || r.result === '大失败') {
      return { 品质: '糟糕', 失败率: failRate, 检定: r };
    }
  }
  return { 品质: quality, 失败率: 0 };
}

function _cookYieldMod(cookSkill) {
  var skl = Number(cookSkill) || 0;
  if (skl >= 20) { return 1.5; }
  if (skl >= 15) { return 1.2; }
  if (skl >= 10) { return 1.1; }
  return 1.0;
}

/* 公式以DDL骰子引擎为准，禁止本地修改 */
function _poisonRate(cookSkill) {
  return Math.max(1, 20 - (Number(cookSkill) || 0) * 1.5);
}

function _rotProgress(daysStored, rotDays, temp) {
  var ds = Number(daysStored) || 0;
  var rd = Number(rotDays) || 1;
  var coeff = _tempRotCoeff(temp);
  var progress = (ds / rd) * 100 * coeff;
  return Math.min(100, Math.round(progress * 100) / 100);
}

function _rotStage(progress) {
  var p = Number(progress) || 0;
  if (p >= 100) { return { 阶段: '完全腐烂', 营养修正: 0.0, 中毒附加: 100, 可食用: false }; }
  if (p >= 81) { return { 阶段: '腐坏中', 营养修正: 0.7, 中毒附加: 15, 可食用: true }; }
  if (p >= 51) { return { 阶段: '不太新鲜', 营养修正: 0.9, 中毒附加: 0, 可食用: true }; }
  return { 阶段: '新鲜', 营养修正: 1.0, 中毒附加: 0, 可食用: true };
}

function _nutritionNeed(age, pregnant) {
  var a = Number(age) || 20;
  var need = 1.6;
  if (a < 16) { need = 1.0; }
  if (pregnant > 0 && pregnant <= 15) { need = 2.0; }
  else if (pregnant > 15 && pregnant <= 30) { need = 2.2; }
  else if (pregnant > 30) { need = 2.4; }
  return need;
}

function _coldStorageTemp(wallType, coolerType, outsideTemp) {
  var ot = Number(outsideTemp) || 20;
  var base = ot;
  if (wallType === '双层石墙') { base -= 8; }
  if (coolerType === '风冷机') { base = Math.min(base, 5); base = Math.max(base, 0); }
  else if (coolerType === '高级冷冻柜') { base = -10; }
  return base;
}

function _foodTempComfort(temp) {
  var t = Number(temp) || 20;
  if (t >= 16 && t <= 26) { return { 舒适: true, 工作速度修正: 1.0, 健康损害: 0 }; }
  var diff = 0;
  var speed = 1.0;
  var dmg = 0;
  if (t < 16) { diff = 16 - t; }
  else { diff = t - 26; }
  speed = Math.max(0.5, 1.0 - diff * 0.03);
  dmg = Math.round(diff * 0.5 * 100) / 100;
  return { 舒适: false, 工作速度修正: speed, 健康损害: dmg };
}

var p1Need = _nutritionNeed(p1Age, p1Pregnant);
var rotCoeff = _tempRotCoeff(temperature);
var comfort = _foodTempComfort(temperature);
_%>
<烹饪系统就绪>
[当前食物状态]
温度: <%= temperature %>°C (腐烂系数:<%= rotCoeff %>)
季节: <%= season %> 时段: <%= timeSlot %>
银两: <%= silver %>

殖民者厨艺:
1. <%= p1Name %> - 厨艺:<%= p1Cook %> 年龄:<%= p1Age %> 孕期:<%= p1Pregnant %> 营养需求:<%= p1Need %>N/天
2. <%= p2Name %> - 厨艺:<%= p2Cook %>
舒适度: <%= comfort.舒适 ? '舒适' : '不适' %> 工作速度修正:×<%= comfort.工作速度修正 %> 健康损害:<%= comfort.健康损害 %>

[烹饪规则]
配方查询: 查FOOD_DB获取食材/营养/基础耗时/腐烂天数
烹饪时间公式: 实际时间 = 基础时间 / (1 + 厨艺技能 × 0.1)
  示例: <%= p1Name %>厨艺<%= p1Cook %> → 耗时系数×<%= _cookTime(1, p1Cook) %>

品质判定(技能分级):
  技能0-3: 糟糕/普通 (失败率 = max(0, 40 - skill×2)%)
  技能4-7: 良好
  技能8-12: 优秀
  技能13-17: 大师
  技能18-20: 传奇
  示例: <%= p1Name %>厨艺<%= p1Cook %> → 品质:<%= _cookQuality(p1Cook, 'cook_demo').品质 %>

产出修正: 技能≥10 ×1.1 / ≥15 ×1.2 / ≥20 ×1.5
  <%= p1Name %>产出修正:×<%= _cookYieldMod(p1Cook) %>

中毒概率: max(1, 20 - 厨艺技能 × 1.5)%
  <%= p1Name %>中毒率:<%= _poisonRate(p1Cook) %>%

营养值系统:
  成年人(≥16岁): 1.6N/天
  未成年人(<16岁): 1.0N/天
  孕妇: 孕初期(1-15日)2.0N / 中期(16-30日)2.2N / 晚期(31日+)2.4N

[腐烂规则]
腐烂进度公式: 进度 = (存放天数 / 腐烂天数) × 100 × 温度系数
  当前温度系数: <%= rotCoeff %> (查ROT_TEMP_DB)

温度系数表:
  <-5°C: 0.0 (冷冻不腐)
  -5~0°C: 0.1
  0~5°C: 0.3
  5~10°C: 0.5
  10~20°C: 1.0
  20~30°C: 1.5
  30~40°C: 2.5
  >40°C: 4.0

腐烂阶段:
  0-50%: 新鲜 (营养×1.0, 无中毒)
  51-80%: 不太新鲜 (营养×0.9, 无中毒)
  81-99%: 腐坏中 (营养×0.7, 中毒+15%)
  100%: 完全腐烂 (不可食用)

冷库系统:
  双层石墙隔热: -8°C
  风冷机: 维持0~5°C (功耗200W)
  高级冷冻柜: -10°C (功耗400W)
  示例: 双层石墙+风冷机,外温<%= temperature %>°C → 冷库温度<%= _coldStorageTemp('双层石墙', '风冷机', temperature) %>°C

[温度系统]
舒适温度区间: 16-26°C
偏离舒适区: 工作速度下降(每度-3%), 健康损害(每度+0.5)
衣物保温修正: 根据衣物类型增加舒适区间(皮衣+5°C上限/防寒服+15°C上限)
昼夜温差: 夜间温度通常-5°C(温带)~-10°C(沙漠)
极端天气: 热浪(+15°C), 寒潮(-20°C), 火山冬天(-30°C且光照×0.2)

[行为校验要求]
烹饪行为必须输出行为校验块:
  行为类型: 烹饪/屠宰/酿酒/采集/储存
  执行者: 殖民者姓名
  技能等级: 厨艺技能值
  配方: 食物名称(查FOOD_DB获取营养/基础耗时/腐烂天数)
  烹饪时间: _cookTime()计算结果
  品质判定: _cookQuality()结果(糟糕/普通/良好/优秀/大师/传奇)
  产出修正: _cookYieldMod()结果
  中毒率: _poisonRate()计算
  营养产出: 基础营养×产出修正
  腐烂进度: _rotProgress()计算(如涉及储存)
  腐烂阶段: _rotStage()判定
</烹饪系统就绪>

@@generate_before
<%_
/* 电力系统控制器 P1-12
   读取殖民地电力状态，输出电力规则与行为校验要求 */

/* _hashSeed/_lcgRoll 定义在DDL确定性骰子引擎.txt，此处通过EJS执行顺序保证可用 */

/* 风力发电判定表 (确定性骰子: 10%无风/30%微风/40%中风/18%强风/2%风暴) */
function _windPower(seed) {
  var roll = _lcgRoll(seed, 1, 100)[0];
  if (roll <= 10) { return { power: 0, label: '无风', note: '0W' }; }
  if (roll <= 40) { return { power: 500, label: '微风', note: '500W' }; }
  if (roll <= 80) { return { power: 1500, label: '中风', note: '1500W' }; }
  if (roll <= 98) { return { power: 3000, label: '强风', note: '3000W' }; }
  return { power: 0, label: '风暴', note: '损坏5%' };
}

