/* 公式以DDL骰子引擎为准，禁止本地修改 */
/* 建造耗时公式: 实际时间 = 基础耗时 / (1 + 建设技能 x 0.08) */
function _buildTime(baseTime, skill) {
  var skl = Number(skill) || 0;
  var actual = baseTime / (1 + skl * 0.08);
  return Math.round(actual * 100) / 100;
}

/* 品质判定: 根据技能等级返回HP修正与品质等级 (与制作系统_qualityCheck分离,避免同名混淆) */
function _buildQuality(skill) {
  var skl = Number(skill) || 0;
  if (skl <= 3) {
    return { grade: '糟糕', hpMod: 0.8, note: '糟糕品质' };
  }
  if (skl <= 7) {
    return { grade: '普通', hpMod: 1.0, note: '普通品质' };
  }
  if (skl <= 10) {
    return { grade: '良好', hpMod: 1.1, note: '良好品质' };
  }
  if (skl <= 13) {
    return { grade: '优秀', hpMod: 1.2, note: '优秀品质' };
  }
  if (skl <= 16) {
    return { grade: '大师', hpMod: 1.3, note: '大师品质' };
  }
  return { grade: '传奇', hpMod: 1.5, note: '传奇品质' };
}

/* 维修规则: 维修速度 = 1 + 建设技能 x 0.05, 恢复HP = 建设技能 x 2 */
function _repairRule(skill) {
  var skl = Number(skill) || 0;
  var repairSpeed = 1 + skl * 0.05;
  var repairHP = skl * 2;
  return {
    修理速度: Math.round(repairSpeed * 100) / 100,
    恢复HP: repairHP,
    材料消耗: '原建筑材料 x 25%'
  };
