/* 拆除回收: 拆除速度 = 1 + 建设技能 x 0.08, 回收率 = min(75, 25 + 建设技能 x 2.5) */
function _demolishRule(skill) {
  var skl = Number(skill) || 0;
  var recovery = Math.min(75, 25 + skl * 2.5);
  return {
    拆除速度: Math.round((1 + skl * 0.08) * 100) / 100,
    回收率: Math.round(recovery * 100) / 100
  };
}

