var lastRaidDay = Number(getvar('stat_data.事件计时器.上次袭击日', { scope: 'local', defaults: 0 })) || 0;
var lastTradeDay = Number(getvar('stat_data.事件计时器.上次贸易日', { scope: 'local', defaults: 0 })) || 0;
var lastDiseaseDay = Number(getvar('stat_data.事件计时器.上次疾病日', { scope: 'local', defaults: 0 })) || 0;
var lastMentalDay = Number(getvar('stat_data.事件计时器.上次精神事件日', { scope: 'local', defaults: 0 })) || 0;
var lastSpecialDay = Number(getvar('stat_data.事件计时器.上次特殊事件日', { scope: 'local', defaults: 0 })) || 0;
var lastMeteorDay = Number(getvar('stat_data.事件计时器.上次陨石日', { scope: 'local', defaults: 0 })) || 0;
var lastMigrationDay = Number(getvar('stat_data.事件计时器.上次动物迁徙日', { scope: 'local', defaults: 0 })) || 0;

var storytellerParams = {
  '卡桑德拉': { '拓荒期': 0.3, '发展期': 0.6, '繁荣期': 1.0, '终局期': 1.8 },
  '菲比': { '拓荒期': 0.1, '发展期': 0.3, '繁荣期': 0.6, '终局期': 1.0 },
  '兰迪': { '拓荒期': 'random', '发展期': 'random', '繁荣期': 'random', '终局期': 'random' }
};

function _storytellerFactor(storyteller, phase, seed) {
  var params = storytellerParams[storyteller] || storytellerParams['卡桑德拉'];
  var base = params[phase];
  if (base === 'random') {
    var roll = _lcgRoll(seed + '_randy', 1, 100)[0];
    if (phase === '拓荒期') { return Math.round((0.1 + roll / 100 * 0.7) * 100) / 100; }
    if (phase === '发展期') { return Math.round((0.2 + roll / 100 * 1.0) * 100) / 100; }
    if (phase === '繁荣期') { return Math.round((0.3 + roll / 100 * 1.7) * 100) / 100; }
    return Math.round((0.5 + roll / 100 * 2.5) * 100) / 100;
  }
  return base;
}

function _checkCooldown(gameDay, lastDay, minInterval) {
  var elapsed = gameDay - lastDay;
  return { elapsed: elapsed, ready: elapsed >= minInterval, remaining: Math.max(0, minInterval - elapsed) };
}

function _eventRoll(seed, probability) {
  var roll = _lcgRoll(seed, 1, 100)[0];
  return { roll: roll, success: roll <= probability * 100 };
}

var stMod = _storytellerFactor(storyteller, phase, 'storyteller_' + gameDay);
var disasterCD = _checkCooldown(gameDay, lastSpecialDay, 15);
var tradeCD = _checkCooldown(gameDay, lastTradeDay, 7);
var diseaseCD = _checkCooldown(gameDay, lastDiseaseDay, 20);
