  { type: '疾病', cooldown: '15-30天', examples: '流感/瘟疫/感染/伤口感染' },
  { type: '精神事件', cooldown: '每轮', examples: '崩溃/灵感/通灵 (心情触发)' },
  { type: '特殊', cooldown: '20-40天', examples: '陨石/难民/逃亡者/远古危险' },
  { type: '机械族', cooldown: '30-60天', examples: '机械族袭击/机械集群 (需触发条件)' }
];
_%>
