<%_
var gameDay = Number(getvar('stat_data.殖民地.游戏日', { scope: 'local', defaults: 1 })) || 1;
var timeSlot = getvar('stat_data.殖民地.时段', { scope: 'local', defaults: '清晨' }) || '清晨';
var hygiene = Number(getvar('stat_data.殖民地.卫生条件', { scope: 'local', defaults: 50 })) || 50;
var temperature = Number(getvar('stat_data.殖民地.温度', { scope: 'local', defaults: 20 })) || 20;
var biome = getvar('stat_data.殖民地.biome', { scope: 'local', defaults: '温带森林' }) || '温带森林';

/* 疾病数据库 - RimWorld原版疾病 */
var DISEASE_DB = {
  '流感':       { contagion: 30, duration: 5,  severity: '轻度',   treat: '基础药品', immunityRate: 8 },
  '疟疾':       { contagion: 20, duration: 7,  severity: '中度',   treat: '奎宁',     immunityRate: 6 },
  '感染':       { contagion: 0,  duration: 3,  severity: '重度',   treat: '抗生素',   immunityRate: 5 },
  '瘟疫':       { contagion: 60, duration: 10, severity: '极重度', treat: '高级药品', immunityRate: 4 },
  '肌肉寄生虫': { contagion: 10, duration: 4,  severity: '轻度',   treat: '基础药品', immunityRate: 9 }
};

/* 疾病影响表 - 按严重度 */
var DISEASE_IMPACT = {
  '轻度':   { workEff: 0.8, mood: -5,  bedRest: false },
  '中度':   { workEff: 0.5, mood: -15, bedRest: true  },
  '重度':   { workEff: 0.2, mood: -30, bedRest: true  },
  '极重度': { workEff: 0,   mood: -50, bedRest: true  }
};

/* 疾病触发判定 - 基于卫生条件/温度/biome */
function _diseaseTrigger(seed) {
  var roll = _lcgRoll(seed, 1, 100)[0];
  /* 卫生条件越差,触发概率越高 */
  var hygieneFactor = Math.max(0, (100 - hygiene) / 100);
  /* 极端温度增加疾病风险 */
  var tempFactor = (temperature < -5 || temperature > 35) ? 0.3 : 0;
  /* biome修正 */
  var biomeFactor = 0;
  if (biome === '热带雨林') { biomeFactor = 0.4; }
  else if (biome === '沙漠' || biome === '冻原') { biomeFactor = 0.2; }
  var triggerChance = Math.round((hygieneFactor * 30) + (tempFactor * 100) + (biomeFactor * 100));
  if (triggerChance > 80) { triggerChance = 80; }
  if (roll > triggerChance) { return { triggered: false, disease: '无', chance: triggerChance }; }
  /* 根据biome和条件选择疾病类型 */
  var typeRoll = _lcgRoll(seed + '_type', 1, 100)[0];
  if (biome === '热带雨林') {
    if (typeRoll <= 40) { return { triggered: true, disease: '疟疾', chance: triggerChance }; }
    if (typeRoll <= 70) { return { triggered: true, disease: '流感', chance: triggerChance }; }
    if (typeRoll <= 90) { return { triggered: true, disease: '肌肉寄生虫', chance: triggerChance }; }
    return { triggered: true, disease: '瘟疫', chance: triggerChance };
  }
  if (biome === '冻原' || temperature < 0) {
    if (typeRoll <= 60) { return { triggered: true, disease: '流感', chance: triggerChance }; }
    return { triggered: true, disease: '感染', chance: triggerChance };
  }
  if (hygiene < 20) {
    if (typeRoll <= 35) { return { triggered: true, disease: '瘟疫', chance: triggerChance }; }
    if (typeRoll <= 70) { return { triggered: true, disease: '流感', chance: triggerChance }; }
    return { triggered: true, disease: '感染', chance: triggerChance };
  }
  if (typeRoll <= 50) { return { triggered: true, disease: '流感', chance: triggerChance }; }
  if (typeRoll <= 80) { return { triggered: true, disease: '肌肉寄生虫', chance: triggerChance }; }
  return { triggered: true, disease: '疟疾', chance: triggerChance };
}

/* 疾病发展阶段: 0潜伏→1轻度→2中度→3重度→4极重度→5康复/6死亡 */
function _diseaseProgress(stage) {
  var s = Number(stage) || 0;
  if (s === 0) { return { stage: 1, label: '轻度',   detail: '症状显现,工作效率下降' }; }
  if (s === 1) { return { stage: 2, label: '中度',   detail: '症状加重,需卧床休息' }; }
  if (s === 2) { return { stage: 3, label: '重度',   detail: '症状严重,强制卧床' }; }
  if (s === 3) { return { stage: 4, label: '极重度', detail: '濒死风险,需紧急治疗' }; }
  return { stage: s, label: '稳定', detail: '阶段不推进' };
}

/* 治疗效果判定 - medLevel含skill/medType/bedRest */
function _diseaseTreat(medLevel, disease) {
  var skill = Number(medLevel.skill) || 0;
  var medType = medLevel.medType || '无';
  var bedRest = medLevel.bedRest ? true : false;
  var diseaseData = DISEASE_DB[disease] || { severity: '轻度', treat: '基础药品' };
  /* 药品系数与技能门槛 */
  var medFactor = 0.3;
  var medOk = false;
  if (medType === '基础药品') { medFactor = 1.0; medOk = skill >= 3; }
  else if (medType === '高级药品') { medFactor = 1.5; medOk = skill >= 5; }
  else if (medType === '抗生素' && diseaseData.treat === '抗生素') { medFactor = 1.3; medOk = skill >= 4; }
  else if (medType === '奎宁' && diseaseData.treat === '奎宁') { medFactor = 1.4; medOk = skill >= 4; }
  else if (medType === '高级药品' && diseaseData.treat === '高级药品') { medFactor = 1.5; medOk = skill >= 5; }
  /* 医疗技能修正: 1 + skill×0.05 */
  var skillMod = 1 + (skill * 0.05);
  /* 卧床修正: 免疫力累积+2/楼层 */
  var bedMod = bedRest ? 2 : 0;
  var treatRate = medFactor * skillMod;
  var immunityGain = bedMod;
  var success = medOk && (treatRate >= 1.0);
  return {
    success: success,
    treatRate: treatRate.toFixed(2),
    immunityGain: immunityGain,
    skillMod: skillMod.toFixed(2),
    medFactor: medFactor,
    bedMod: bedMod,
    detail: medOk ? '治疗有效' : '药品/技能不足,仅靠免疫力'
  };
}

/* 自愈判定 - 基于免疫力 */
function _diseaseRecover(immunity, disease) {
  var imm = Number(immunity) || 0;
  var diseaseData = DISEASE_DB[disease] || { immunityRate: 5 };
  if (imm >= 100) { return { recovered: true, detail: '免疫力达标,自愈成功' }; }
  var roll = _lcgRoll('recover_' + disease + '_' + imm, 1, 100)[0];
  var recoverChance = Math.floor(imm * 0.8);
  if (roll <= recoverChance) { return { recovered: true, detail: '自愈成功,免疫力:' + imm }; }
  return { recovered: false, detail: '自愈失败,需继续治疗' };
}

/* 免疫力累积 - 每游戏日推进 */
function _immunityBuild(immunity, disease) {
  var imm = Number(immunity) || 0;
  var diseaseData = DISEASE_DB[disease] || { immunityRate: 5 };
  var gain = diseaseData.immunityRate || 5;
  var newImm = imm + gain;
  if (newImm > 100) { newImm = 100; }
  return { immunity: newImm, gain: gain, detail: '免疫力+' + gain + ' (当前' + newImm + ')' };
}

/* 读取殖民者疾病状态 */
function _readColonistDisease(idx) {
  var prefix = 'stat_data.殖民者_' + idx;
  var disease = getvar(prefix + '.疾病', { scope: 'local', defaults: '无' }) || '无';
  var stage = Number(getvar(prefix + '.疾病阶段', { scope: 'local', defaults: 0 })) || 0;
  var immunity = Number(getvar(prefix + '.免疫力', { scope: 'local', defaults: 0 })) || 0;
  var bedRest = getvar(prefix + '.卧床', { scope: 'local', defaults: false }) || false;
  var medSkill = Number(getvar(prefix + '.医疗', { scope: 'local', defaults: 5 })) || 5;
  var mood = Number(getvar(prefix + '.心情', { scope: 'local', defaults: 50 })) || 50;
  return {
    name: idx === '主角' ? '主角' : '殖民者' + idx,
    disease: disease,
    stage: stage,
    immunity: immunity,
    bedRest: bedRest,
    medSkill: medSkill,
    mood: mood
  };
}

var colonists = [
