  '高科技研究台': { 速度: 2.0, 耗电: 400, 组件: 3, 备注: '能量武器/高级组件,需组件×3' }
};

/* 品质分级表 QUALITY_DB
   字段: 区间(判定百分比), 价值(价值系数), 美观(美观修正), 等级(品质名称) */
var QUALITY_DB = [
  { 等级: '糟糕', 区间: [0, 10], 价值: 0.5, 美观: -10 },
  { 等级: '普通', 区间: [11, 50], 价值: 1.0, 美观: 0 },
  { 等级: '良好', 区间: [51, 75], 价值: 1.3, 美观: 5 },
