/* 任务类型表 QUEST_DB
   字段: 类型(任务大类), 描述(任务说明), 奖励银两(基础银两), 奖励关系(关系增量),
        奖励物品(物品奖励), 难度基础(基础难度1-5), 最小关系(触发最小关系值) */
var QUEST_DB = {
  '求助信': {
    类型: '求助信', 描述: '派系据点遭袭/疾病/饥荒,请求殖民者前往救援',
    奖励银两: 200, 奖励关系: 10, 奖励物品: '无',
