3. 物资请求: 交付物资 (奖励: 银两150 + 关系+3) 难度2星 超时7天 需关系>=10
   → 派系急需食物/药品/材料
4. 特殊任务: 护送/探索/回收 (奖励: 银两300 + 关系+15 + 稀有物品) 难度5星 超时7天 需关系>=20
   → 高风险高回报任务

[难度分级表 DIFFICULTY_DB]
★ 简单: 检定修正×1.2 敌人强度×0.6
★★ 普通: 检定修正×1.0 敌人强度×1.0
★★★ 困难: 检定修正×0.8 敌人强度×1.5
★★★★ 险恶: 检定修正×0.6 敌人强度×2.0
★★★★★ 致命: 检定修正×0.4 敌人强度×3.0

[任务触发规则]
1. 触发判定: _questTrigger(faction, relation, day)
   冷却: 菲比5天 / 兰迪2天 / 卡桑德拉4天
   概率: LCG骰子1d100 ≤50 触发
   关系门槛: <-50 敌对不触发 / <10 仅求助信+赏金 / <20 +物资请求 / >=20 全类型
   演示: <%= factionList[0].name %> 关系<%= factionList[0].relation %> → <%= triggerDemo.触发 ? '触发' : '未触发' %> (<%= triggerDemo.原因 %>)
   可用类型: <%= triggerDemo.可用类型 ? triggerDemo.可用类型.join('/') : '无' %>

2. 难度计算: _questDifficulty(quest, factionLevel)
   最终难度 = 基础难度 + floor((派系等级-1)/2) + 阶段修正(繁荣期+1)
   上限5星(致命),下限1星(简单)
   演示: 求助信 + 派系等级1 → <%= diffDemo.星级 %> <%= diffDemo.名称 %> (检定修正×<%= diffDemo.检定修正 %>, 敌人强度×<%= diffDemo.敌人强度 %>)

3. 奖励计算: _questReward(quest, success)
   成功等级: 大成功(银两×1.5+关系+5) / 普通/极难成功(基础) / 失败(银两0/关系-2) / 大失败(银两0/关系-5)
   社交修正: 银两 × (1 + 社交×0.02)
   演示(求助信):
     普通成功: 银两<%= rewardSuccessDemo.银两 %> + 关系+<%= rewardSuccessDemo.关系 %> 物品<%= rewardSuccessDemo.物品 %>
     大成功: 银两<%= rewardCritDemo.银两 %> + 关系+<%= rewardCritDemo.关系 %> 物品<%= rewardCritDemo.物品 %>
     失败: 银两<%= rewardFailDemo.银两 %> + 关系<%= rewardFailDemo.关系 %> 物品<%= rewardFailDemo.物品 %>

4. 超时判定: _questTimeout(quest, startDay)
   超时限制: 7天 (所有任务统一)
   超时后果: 任务失败,关系-3
   演示: 求助信 + 3天前开始 → 已用<%= timeoutDemo.已用天数 %>天,剩余<%= timeoutDemo.剩余天数 %>天 <%= timeoutDemo.超时 ? '(已超时)' : '(未超时)' %>

[任务执行流程]
1.触发判定 → 2.选择任务类型 → 3.难度计算 → 4.派遣殖民者 → 5.执行检定(_check) → 6.奖励发放 → 7.关系更新

[行为校验要求]
派系任务行为必须输出行为校验块:
<派系任务校验>
- 派系名称: [派系名]
- 当前关系: [关系值] [关系层级]
- 任务类型: [求助信/赏金/物资请求/特殊任务]
- 任务描述: [任务说明]
- 难度星级: [1-5星] [难度名称]
- 检定修正: [×0.4~1.2]
- 敌人强度: [×0.6~3.0]
- 执行者: [殖民者姓名]
- 检定结果: [_check结果(大成功/极难成功/普通成功/失败/大失败)]
- 奖励银两: [银两数] [含社交修正]
- 奖励关系: [关系增减]
- 奖励物品: [物品名/无]
- 超时状态: [剩余天数/已超时]
- 银两变动: [扣除/增加/余额]
- 关系变动: [触发原因/增减值/新关系值]
</派系任务校验>

[派系任务系统说明]
本控制器为派系任务统一入口,所有派系任务触发/难度/奖励/超时必须经此判定。
任务类型表(QUEST_DB)定义4类任务,奖励与难度基础值固定,可被社交技能修正。
难度分级表(DIFFICULTY_DB)定义5级难度,影响检定阈值与敌人强度。
触发判定依赖DDL确定性骰子引擎(_lcgRoll),确保触发概率可追溯可复现。
任务检定使用_check函数,难度修正影响检定阈值(简单×1.2/致命×0.4)。
与派系贸易系统联动:任务奖励的银两/关系变更需同步到殖民地.银两和派系.xxx.关系变量。
超时统一7天,超时后任务失败且关系-3,需与时间推进调度器联动检测。
</派系任务系统就绪>

@@generate_before
<%_
/* 轨道贸易系统控制器
   定义轨道贸易商船/触发/价格/成功率,行为校验入口 */

var gameDay = Number(getvar('stat_data.殖民地.游戏日', { scope: 'local', defaults: 1 })) || 1;
var phase = getvar('stat_data.殖民地.阶段', { scope: 'local', defaults: '拓荒期' }) || '拓荒期';
var silver = Number(getvar('stat_data.殖民地.银两', { scope: 'local', defaults: 800 })) || 800;
var p1Social = Number(getvar('stat_data.殖民者_主角.社交', { scope: 'local', defaults: 5 })) || 5;
var hasSignal = Number(getvar('stat_data.殖民地.贸易信号器', { scope: 'local', defaults: 0 })) || 0;
var lastOrbitalDay = Number(getvar('stat_data.事件计时器.上次轨道贸易日', { scope: 'local', defaults: 0 })) || 0;
var lastTraderType = getvar('stat_data.事件计时器.上次商船类型', { scope: 'local', defaults: '无' }) || '无';

/* 贸易信号器建筑定义
   需组件×5 + 钢铁×10建造,提供轨道贸易触发能力 */
var SIGNAL_BUILDING = {
  名称: '贸易信号器',
  建造成本: { 组件: 5, 钢铁: 10 },
  建造技能: '建设',
  建造耗时: 8,
  耗电: 200,
  备注: '建造后可触发轨道贸易,商船定期来访'
};

/* 贸易商船类型表 TRADER_DB
   字段: 类型(商船大类), 商品(可交易商品类别), 间隔(来访间隔天数),
        买入修正(买入价修正), 卖出修正(卖出价修正), 备注(商船说明) */
var TRADER_DB = {
  '补给船': {
    类型: '补给船', 商品: '日用品/食物/药品', 间隔: 7,
    买入修正: 1.1, 卖出修正: 1.15, 备注: '基础物资补给,最常见'
  },
  '武器商': {
    类型: '武器商', 商品: '武器/弹药/护甲', 间隔: 14,
    买入修正: 1.1, 卖出修正: 1.15, 备注: '军火商船,武器装备交易'
  },
  '资源商': {
    类型: '资源商', 商品: '材料/组件/高级组件', 间隔: 10,
    买入修正: 1.1, 卖出修正: 1.15, 备注: '原材料与组件供应'
  },
  '奢侈品商': {
    类型: '奢侈品商', 商品: '艺术品/稀有物品', 间隔: 21,
    买入修正: 1.1, 卖出修正: 1.15, 备注: '高端商品,高价值交易'
  },
  '黑市商': {
    类型: '黑市商', 商品: '违禁品/奴隶/特殊物品', 间隔: 30,
    买入修正: 1.1, 卖出修正: 1.15, 备注: '非法交易,高风险高回报'
  }
};

/* 轨道贸易商品表 ORBITAL_GOODS_DB
   每个商船类型的可交易商品列表(基础估值参考各数值表) */
var ORBITAL_GOODS_DB = {
  '补给船': {
    出售: ['简餐', '精制餐', '草药', '草药包', '布', '皮革', '木材', '石块'],
    收购: ['钢铁', '白银', '黄金', '皮革', '草药', '多余食物']
  },
  '武器商': {
    出售: ['短弓', '长弓', '左轮', '步枪', '霰弹枪', '狙击枪', '子弹', '皮甲', '防弹衣', '战术甲'],
    收购: ['白银', '黄金', '武器', '护甲', '钢铁', '组件']
  },
  '资源商': {
    出售: ['钢铁', '布', '皮革', '玻璃', '黄金', '铀', '组件', '高级组件', '化学燃料'],
    收购: ['白银', '多余材料', '食物', '草药', '皮革', '木材']
  },
  '奢侈品商': {
    出售: ['黑曜石', '翡翠', '玉石', '黄金', '灵魂草', '高级药', '高级组件'],
    收购: ['艺术品', '稀有物品', '黄金', '白银', '珠宝', '高级组件']
  },
  '黑市商': {
    出售: ['路西弗', '奴隶', '黑市武器', '能量电池', '稀有材料', '特殊信物'],
    收购: ['白银', '黄金', '艺术品', '违禁品', '奴隶', '稀有物品']
  }
};

/* 轨道贸易触发判定
   signal=是否有贸易信号器(0/1), day=当前游戏日
   返回: 触发判定结果 */
function _orbitalTradeTrigger(signal, day) {
  var sig = Number(signal) || 0;
  var d = Number(day) || 1;
  if (sig !== 1) {
    return { 触发: false, 原因: '未建造贸易信号器,无法呼叫轨道贸易', 需建造: '贸易信号器(组件×5+钢铁×10)' };
  }
  var daysSince = d - lastOrbitalDay;
  /* 检查各商船类型是否到达来访间隔 */
  var availableTraders = [];
  var traderNames = Object.keys(TRADER_DB);
  for (var i = 0; i < traderNames.length; i++) {
    var tName = traderNames[i];
    var trader = TRADER_DB[tName];
    var interval = Number(trader.间隔) || 7;
    if (daysSince >= interval) {
      availableTraders.push({
        类型: tName,
        间隔: interval,
        商品: trader.商品,
        距上次: daysSince + '天'
      });
    }
  }
  if (availableTraders.length === 0) {
    var nextMinInterval = 7;
    var nextTrader = '补给船';
    for (var j = 0; j < traderNames.length; j++) {
      var tn = traderNames[j];
      var intv = Number(TRADER_DB[tn].间隔) || 7;
      var remain = intv - daysSince;
      if (remain > 0 && remain < nextMinInterval) {
        nextMinInterval = remain;
        nextTrader = tn;
      }
    }
    return {
      触发: false,
      原因: '无商船到达,距下次最近商船(' + nextTrader + ')还有' + nextMinInterval + '天',
      距上次贸易: daysSince + '天',
      下次商船: nextTrader,
      剩余天数: nextMinInterval
    };
  }
  /* LCG骰子选择来访商船(从可用商船中随机选一个) */
  var selectRoll = _lcgRoll('orbital_select_' + d, 1, availableTraders.length)[0];
  var selected = availableTraders[selectRoll - 1];
  return {
    触发: true,
    原因: '商船到达,可进行轨道贸易',
    商船类型: selected.类型,
    商品范围: selected.商品,
    距上次贸易: selected.距上次,
    可用商船: availableTraders,
    选中商船: selected.类型,
    骰值: selectRoll
  };
}

/* 轨道贸易买入价(比地面贸易贵10%)
   item=商品基础估值, traderType=商船类型(查TRADER_DB)
   返回: 买入价 */
function _orbitalBuyPrice(item, traderType) {
  var baseValue = Number(item) || 1;
  var tt = String(traderType) || '补给船';
  var trader = TRADER_DB[tt] || TRADER_DB['补给船'];
  var buyMod = Number(trader.买入修正) || 1.1;
  /* 社交技能修正: 每点社交-1%买入价 */
  var socialMod = Math.max(0.5, 1 - p1Social * 0.01);
  var raw = baseValue * buyMod * socialMod;
  return Math.round(raw * 100) / 100;
}

/* 轨道贸易卖出价(比地面贸易高15%)
   item=商品基础估值, traderType=商船类型(查TRADER_DB)
   返回: 卖出价 */
function _orbitalSellPrice(item, traderType) {
  var baseValue = Number(item) || 1;
  var tt = String(traderType) || '补给船';
  var trader = TRADER_DB[tt] || TRADER_DB['补给船'];
  var sellMod = Number(trader.卖出修正) || 1.15;
  /* 社交技能修正: 每点社交+1%卖出价 */
  var socialMod = 1 + p1Social * 0.01;
  var raw = baseValue * sellMod * socialMod;
  return Math.round(raw * 100) / 100;
}

/* 轨道贸易成功率
   skill=社交技能, amount=交易银两总额
   返回: 贸易检定结果 */
function _orbitalTradeSuccess(skill, amount) {
  var skl = Number(skill) || 0;
  var amt = Number(amount) || 0;
  var threshold = skl * 5;
  /* 大额交易难度提升: 每100银两阈值-5 */
  var amountPenalty = Math.floor(amt / 100) * 5;
  var adjustedThreshold = Math.max(5, threshold - amountPenalty);
  var checkResult = _check(adjustedThreshold, 'orbital_trade_' + gameDay, '普通');
  return {
    阈值: adjustedThreshold,
    基础阈值: threshold,
    大额惩罚: amountPenalty,
    交易额: amt,
    骰值: checkResult.roll,
    结果: checkResult.result,
    成功: (checkResult.result !== '失败' && checkResult.result !== '大失败')
  };
}

/* 触发演示 */
var triggerDemo = _orbitalTradeTrigger(hasSignal, gameDay);
var buyDemo = _orbitalBuyPrice(3, '补给船');
var sellDemo = _orbitalSellPrice(3, '补给船');
var buyDemoWeapon = _orbitalBuyPrice(30, '武器商');
var sellDemoWeapon = _orbitalSellPrice(30, '武器商');
var successDemo = _orbitalTradeSuccess(p1Social, 100);
_%>
