function _checkEnding(){
  var structure = Number(getvar('stat_data.殖民地.飞船结构', {scope:'local',defaults:0}))||0;
  var reactor = Number(getvar('stat_data.殖民地.飞船反应堆', {scope:'local',defaults:0}))||0;
  var aiCore = Number(getvar('stat_data.殖民地.飞船AI核心', {scope:'local',defaults:0}))||0;
  var gameDay = Number(getvar('stat_data.殖民地.游戏日', {scope:'local',defaults:1}))||1;
  var silver = Number(getvar('stat_data.殖民地.银两', {scope:'local',defaults:800}))||800;
  var faith = Number(getvar('stat_data.殖民地.信仰值', {scope:'local',defaults:0}))||0;
  var wealth = Number(getvar('stat_data.殖民地.财富总值', {scope:'local',defaults:800}))||800;
  var pollution = Number(getvar('stat_data.殖民地.污染源数量', {scope:'local',defaults:0}))||0;
  var pirateKills = Number(getvar('stat_data.殖民地.海盗击败次数', {scope:'local',defaults:0}))||0;
  var templeCount = Number(getvar('stat_data.殖民地.神庙数量', {scope:'local',defaults:0}))||0;
  var plantCount = Number(getvar('stat_data.殖民地.种植数量', {scope:'local',defaults:0}))||0;
  var techProgress = Number(getvar('stat_data.殖民地.科技完成度', {scope:'local',defaults:0}))||0;
  var tribeRel = Number(getvar('stat_data.派系.部落联盟.关系', {scope:'local',defaults:0}))||0;
  var cityRel = Number(getvar('stat_data.派系.城市邦联.关系', {scope:'local',defaults:0}))||0;
  var merchantRel = Number(getvar('stat_data.派系.商人公会.关系', {scope:'local',defaults:15}))||15;
  var nomadRel = Number(getvar('stat_data.派系.游牧部落.关系', {scope:'local',defaults:5}))||5;
  var animalCount = (Number(getvar('stat_data.动物_1.数量', {scope:'local',defaults:0}))||0) + (Number(getvar('stat_data.动物_2.数量', {scope:'local',defaults:0}))||0);
  var researchSkill = Number(getvar('stat_data.殖民者_主角.研究', {scope:'local',defaults:5}))||5;

  /* 胜利结局 */
  if(structure >= 1 && reactor >= 3 && aiCore >= 1) return '飞船发射';

  /* 失败结局 */
  var aliveCount = 0;
  var totalSurgery = 0;
  var nsfwActive = 0;
  var tier4Count = 0;
  for(var i = 1; i <= 5; i++){
    var name = i === 1 ? '主角' : '' + i;
    var headHp = Number(getvar('stat_data.殖民者_' + name + '.头部', {scope:'local',defaults:100}))||100;
    var surg = Number(getvar('stat_data.殖民者_' + name + '.手术次数', {scope:'local',defaults:0}))||0;
    var nsfwExp = getvar('stat_data.殖民者_' + name + '.NSFW经验值', {scope:'local',defaults:'{}'})||'{}';
    if(headHp > 0) aliveCount++;
    totalSurgery += surg;
    if(nsfwExp !== '{}') nsfwActive++;
    if(surg >= 4) tier4Count++;
  }
  if(aliveCount === 0) return '殖民地覆灭';

  /* 特殊结局 */
  if(tier4Count >= 5) return '全员飞升';
  if(totalSurgery === 0 && nsfwActive === 0 && gameDay >= 100) return '基因纯净';
  if(techProgress >= 100 && researchSkill > 15) return '知识守护者';
  if(pollution === 0 && animalCount > 10 && plantCount > 15) return '生态守护者';
  if(faith === 100 && templeCount >= 1 && gameDay >= 50) return '宗教圣地';
  if(pirateKills >= 3 && silver >= 10000) return '海盗之王';
  if(gameDay >= 50 && faith >= 100) return '邪教飞升';
  if(gameDay >= 50) return '机械飞升';

  /* 中立结局 */
  if(gameDay >= 80 && tribeRel > 50 && cityRel > 50 && merchantRel > 50 && nomadRel > 50) return '和平共存';
  if(gameDay >= 60 && faith >= 80) return '部落同化';
  if(gameDay >= 30 && silver >= 5000) return '流亡商队';
  if(wealth <= 2000 && aliveCount <= 2 && gameDay >= 60) return '隐居山林';

  return '未触发';
}

function _endingProgress(){
  var structure = Number(getvar('stat_data.殖民地.飞船结构', {scope:'local',defaults:0}))||0;
  var reactor = Number(getvar('stat_data.殖民地.飞船反应堆', {scope:'local',defaults:0}))||0;
  var aiCore = Number(getvar('stat_data.殖民地.飞船AI核心', {scope:'local',defaults:0}))||0;
  return Math.floor((structure / 1 + reactor / 3 + aiCore / 1) / 3 * 100);
}
