  '大师': {范围: [15, 20], 称号: '大师', 效率: 1.8}
};

function _gainExp(skillName, success){
  var db = SKILL_GROWTH_DB[skillName] || SKILL_GROWTH_DB['射击'];
  var base = db.基础经验;
  if(!success) base = Math.floor(base * 0.3);
  return base;
}

function _skillLevel(skillValue){
  for(var k in SKILL_LEVEL_DB){
    var range = SKILL_LEVEL_DB[k].范围;
    if(skillValue >= range[0] && skillValue <= range[1]) return k;
  }
  return '新手';
}

function _skillModifier(skillValue){
  var lv = _skillLevel(skillValue);
  return SKILL_LEVEL_DB[lv].效率;
}

function _skillForget(skillName, lastUseDay, currentDay){
  var db = SKILL_GROWTH_DB[skillName] || SKILL_GROWTH_DB['射击'];
  var days = currentDay - lastUseDay;
  if(days >= db.遗忘阈值) return -1;
  if(days >= db.遗忘阈值 * 0.7) return 0;
  return 0;
}

function _inspirationBonus(mood){
  if(mood > 85) return 1.5;
  if(mood > 70) return 1.2;
  if(mood < 30) return 0.7;
  return 1.0;
}

function _expToNextLevel(currentLevel){
  if(currentLevel < 4) return 50;
  if(currentLevel < 7) return 100;
  if(currentLevel < 10) return 200;
  if(currentLevel < 15) return 400;
  return 800;
}

function _dailySkillGrowth(colonist, usedSkills){
  var mood = Number(getvar('stat_data.' + colonist + '.心情', {scope:'local',defaults:50}))||50;
  var inspiration = _inspirationBonus(mood);
  var gains = {};
  for(var i = 0; i < usedSkills.length; i++){
    var sk = usedSkills[i];
    var db = SKILL_GROWTH_DB[sk] || SKILL_GROWTH_DB['射击'];
    gains[sk] = Math.round(db.基础经验 * db.成长系数 * inspiration);
  }
  return gains;
}
