/* 矿脉发现判定: 基于采矿技能与biome修正, 使用DDL骰子引擎判定
   返回是否发现/矿脉类型/矿脉数据/检定结果 */
function _veinDiscover(skill, biome) {
  var skl = Number(skill) || 0;
  var b = String(biome) || '温带森林';
  var bMod = BIOME_MINING_MOD[b] || BIOME_MINING_MOD['温带森林'];
  var score = skl * 5 + 20;
  var seed = 'vein_' + b + '_' + skl;
  var checkResult = _check(score, seed, '普通');
  var discovered = checkResult.result === '普通成功' || checkResult.result === '极难成功' || checkResult.result === '大成功';
  var veinType = null;
  var veinData = null;
  if (discovered) {
    var bonus = 0;
    if (checkResult.result === '大成功') bonus = 0.15;
    else if (checkResult.result === '极难成功') bonus = 0.05;
    var rollSeed = 'veintype_' + seed + '_' + checkResult.roll;
    var typeRoll = _lcgRoll(rollSeed, 1, 100)[0] / 100;
    var cumulative = 0;
    var discoverMod = bMod.发现修正 + bonus;
    for (var k in VEIN_DB) {
      var v = VEIN_DB[k];
      var adjProb = v.发现概率 * discoverMod;
      cumulative += adjProb;
      if (typeRoll <= cumulative / (cumulative + (1 - cumulative) * 0.5)) {
        veinType = k;
        veinData = v;
        break;
      }
    }
    if (!veinType) {
      veinType = '小矿脉';
      veinData = VEIN_DB['小矿脉'];
    }
  }
  return {
    发现: discovered,
    矿脉类型: veinType,
    矿脉数据: veinData,
    biome修正: bMod.发现修正,
    检定: checkResult
  };
}

/* 挖掘速度: 实际速度 = 基础速度 x (1 + 技能 x 0.06) / 硬度修正
   硬度越高速度越慢, 技能越高速度越快
   返回每小时产出单位数 */
function _miningSpeed(skill, mineralHardness) {
  var skl = Number(skill) || 0;
  var hard = Number(mineralHardness) || 5;
  if (hard < 1) hard = 1;
  var base = 10;
  var speed = base * (1 + skl * 0.06) / (hard / 5);
  return Math.round(speed * 100) / 100;
}

/* 挖掘产出: 产出数量 = 矿脉数量 x (0.6 + 技能 x 0.04) x 品质修正
   技能越高产出越多, 大成功额外+20%
   返回实际产出/产出系数/检定结果 */
function _miningYield(skill, veinSize, seed) {
  var skl = Number(skill) || 0;
  var size = Number(veinSize) || 10;
  var score = skl * 5 + 10;
  var sd = String(seed) || 'mine_yield';
  var checkResult = _check(score, sd, '普通');
  var yieldMod = 0.6 + skl * 0.04;
  var bonus = 0;
  if (checkResult.result === '大成功') { yieldMod *= 1.2; bonus = 0.2; }
  else if (checkResult.result === '大失败') { yieldMod *= 0.6; bonus = -0.4; }
  else if (checkResult.result === '失败') { yieldMod *= 0.8; bonus = -0.2; }
  var actual = Math.max(1, Math.round(size * yieldMod));
  return {
    实际产出: actual,
    矿脉数量: size,
    产出系数: Math.round(yieldMod * 100) / 100,
    附加修正: bonus,
    检定: checkResult
  };
}

/* 深层采矿: 深度越大难度越高, 需要更高技能与设备
   返回可达深度/速度修正/可用矿物列表/检定结果 */
function _deepMining(skill, depth) {
  var skl = Number(skill) || 0;
  var dep = Number(depth) || 0;
  var score = skl * 4 + 10;
  var sd = 'deepmine_' + skl + '_' + dep;
  var checkResult = _check(score, sd, '困难');
  var maxDepth = skl * 8 + 20;
  var speedMod = 1.0;
  if (dep > maxDepth) speedMod = 0.3;
  else if (dep > maxDepth * 0.7) speedMod = 0.6;
  else if (dep > maxDepth * 0.5) speedMod = 0.8;
  var available = [];
  for (var k in DEEP_MINERAL_DB) {
    var dm = DEEP_MINERAL_DB[k];
    if (dep >= dm.深度要求 && dep <= maxDepth) {
      available.push(k);
    }
  }
  var success = checkResult.result === '普通成功' || checkResult.result === '极难成功' || checkResult.result === '大成功';
  return {
    可达深度: maxDepth,
    速度修正: speedMod,
    可用矿物: available,
    深度足够: dep <= maxDepth,
    挖掘成功: success,
    检定: checkResult
  };
}

/* 挖掘疲劳: 疲劳值越高挖掘效率越低, 疲劳>=80有塌方风险
   返回效率修正/塌方风险/建议 */
function _miningExhaustion(fatigue) {
  var f = Number(fatigue) || 0;
  var mod = 1.0;
  var risk = 0;
  var advice = '状态良好';
  if (f < 20) { mod = 1.1; advice = '精力充沛,效率+10%'; }
  else if (f < 40) { mod = 1.0; advice = '状态正常'; }
  else if (f < 60) { mod = 0.85; advice = '略显疲惫,建议休息'; }
  else if (f < 80) { mod = 0.7; risk = 0.1; advice = '疲惫不堪,效率-30%'; }
  else { mod = 0.5; risk = 0.3; advice = '极度疲劳,塌方风险高,必须休息'; }
  return {
    疲劳值: f,
    效率修正: mod,
    塌方风险: risk,
    建议: advice
  };
}

/* 矿物估值: 总价值 = 单价 x 数量 x 品质系数(深银/塑钢等深层矿物+10%)
   返回总价值/单价/数量/品质系数 */
function _mineralValue(type, quantity) {
  var t = String(type) || '钢铁';
  var q = Number(quantity) || 0;
  var info = MINERAL_DB[t] || MINERAL_DB['钢铁'];
  var unit = Number(info.估值) || 1;
  var qualityMod = 1.0;
  var isDeep = false;
  if (DEEP_MINERAL_DB[t]) {
    isDeep = true;
    qualityMod = 1.1;
    unit = Number(DEEP_MINERAL_DB[t].估值) || unit;
  }
  var total = Math.round(unit * q * qualityMod * 100) / 100;
  return {
    矿物: t,
    单价: unit,
    数量: q,
    品质系数: qualityMod,
    深层矿物: isDeep,
    总价值: total
  };
}

/* 读取殖民者采矿技能与状态(MVU变量) */
var p1Name = getvar('stat_data.殖民者_主角.姓名', {scope:'local',defaults:''}) || '';
var p1Mining = Number(getvar('stat_data.殖民者_主角.采矿', {scope:'local',defaults:5})) || 5;
var p1Fatigue = Number(getvar('stat_data.殖民者_主角.疲劳', {scope:'local',defaults:20})) || 20;
var p1Mood = Number(getvar('stat_data.殖民者_主角.心情', {scope:'local',defaults:50})) || 50;

var colonyBiome = getvar('stat_data.殖民地.biome', {scope:'local',defaults:'温带森林'}) || '温带森林';

/* 主角采矿演示判定 */
var demoVein = _veinDiscover(p1Mining, colonyBiome);
var demoSpeed = _miningSpeed(p1Mining, 5);
var demoExhaustion = _miningExhaustion(p1Fatigue);
var demoDeepMine = _deepMining(p1Mining, 30);

/* 心情修正: 心情<30挖掘效率-20%, 心情>70挖掘效率+10% */
var moodMod = 1.0;
if (p1Mood < 30) { moodMod = 0.8; }
else if (p1Mood > 70) { moodMod = 1.1; }
