  '极高': { 死亡率: 0.30, 感染率: 0.45, 失败率: 0.40, 麻醉时间: 10, 适用难度: '17-20' }
};

/* _surgeryInfo(type) - 获取手术信息 */
function _surgeryInfo(type) {
  var t = String(type || '缝合');
  var info = SURGERY_DB[t] || SURGERY_DB['缝合'];
  var diff = info.难度;
  var risk;
  if (diff <= 4) { risk = '极低'; }
  else if (diff <= 8) { risk = '低'; }
  else if (diff <= 12) { risk = '中'; }
  else if (diff <= 16) { risk = '高'; }
  else { risk = '极高'; }
  return {
    名称: t,
    难度: diff,
    耗时: info.耗时,
    成功率公式: info.成功率公式,
    失败后果: info.失败后果,
    恢复时间: info.恢复时间,
    所需药品: info.所需药品,
    所需设备: info.所需设备,
    风险等级: risk,
    风险数据: SURGERY_RISK_DB[risk]
  };
}

/* _surgerySuccessRate(skill, difficulty, patientHealth) - 手术成功率计算 */
function _surgerySuccessRate(skill, difficulty, patientHealth) {
  var s = Number(skill) || 0;
  var d = Number(difficulty) || 1;
  var h = Number(patientHealth) || 80;
  /* 基础成功率: skill×4 + health×0.2 + 40 - difficulty×3 */
  var base = (s * 4) + (h * 0.2) + 40 - (d * 3);
  /* 难度惩罚: 难度>15时额外递减 */
  if (d > 15) { base -= (d - 15) * 4; }
  /* 年龄修正: 老年患者成功率下降 */
  if (pAge > 60) { base -= (pAge - 60) * 0.5; }
  /* 多次手术累积疲劳 */
  if (pSurgeryCount > 3) { base -= (pSurgeryCount - 3) * 2; }
  /* 上下限钳制 */
  if (base > 98) { base = 98; }
  if (base < 5) { base = 5; }
  return Math.round(base);
}

/* _surgeryFailure(skill, difficulty) - 手术失败后果 */
function _surgeryFailure(skill, difficulty) {
  var s = Number(skill) || 0;
  var d = Number(difficulty) || 1;
  var info = null;
  for (var k in SURGERY_DB) {
    if (SURGERY_DB[k].难度 === d) { info = SURGERY_DB[k]; break; }
  }
  if (!info) { info = SURGERY_DB['缝合']; }
  var baseFailure = info.失败后果;
  var riskLevel;
  if (d <= 4) { riskLevel = '极低'; }
  else if (d <= 8) { riskLevel = '低'; }
  else if (d <= 12) { riskLevel = '中'; }
  else if (d <= 16) { riskLevel = '高'; }
  else { riskLevel = '极高'; }
  var riskData = SURGERY_RISK_DB[riskLevel];
  /* 技能修正: 高技能减轻后果 */
  var mitigate = s >= 10 ? 0.5 : (s >= 6 ? 0.7 : 1.0);
  var finalDeath = Math.round(riskData.死亡率 * mitigate * 100) / 100;
  var finalInfect = Math.round(riskData.感染率 * mitigate * 100) / 100;
  return {
    后果: baseFailure,
    风险等级: riskLevel,
    死亡率: finalDeath,
    感染率: finalInfect,
    技能缓解: mitigate,
    详情: '手术失败[' + baseFailure + '] 风险等级[' + riskLevel + '] 执行技能缓解×' + mitigate
  };
}

/* _organRejection(organType, days) - 器官排斥判定 */
function _organRejection(organType, days) {
  var t = String(organType || '肾');
  var organ = ORGAN_DB[t] || ORGAN_DB['肾'];
  var d = Number(days) || 0;
  var baseReject = organ.排斥概率;
  /* 排斥概率随时间衰减: 前7天最高,之后递减 */
  var timeFactor;
  if (d <= 7) { timeFactor = 1.5; }
  else if (d <= 14) { timeFactor = 1.0; }
  else if (d <= 30) { timeFactor = 0.6; }
  else { timeFactor = 0.3; }
  var currentRisk = Math.round(baseReject * timeFactor * 100) / 100;
  if (currentRisk > 0.95) { currentRisk = 0.95; }
  var stage;
  if (d <= 7) { stage = '急性排斥期'; }
  else if (d <= 30) { stage = '亚急性期'; }
  else { stage = '慢性维持期'; }
  return {
    器官: t,
    存活率: organ.存活率,
    排斥概率: currentRisk,
    基础排斥: baseReject,
    时间因子: timeFactor,
    阶段: stage,
    恢复时间: organ.恢复时间,
    供体要求: organ.供体要求,
    详情: stage + ' 排斥概率' + (currentRisk * 100).toFixed(0) + '%'
  };
}

/* _bionicEffect(bionicType) - 仿生体效果 */
function _bionicEffect(bionicType) {
  var t = String(bionicType || '仿生眼');
  var b = BIONIC_DB[t] || BIONIC_DB['仿生眼'];
  /* 排斥判定: 神经芯片最难适应 */
  var rejectRoll = _lcgRoll('bionic_reject_' + t + '_' + pName, 1, 100)[0];
  var rejectThreshold = Math.round(b.排斥概率 * 100);
  var rejected = rejectRoll <= rejectThreshold;
  return {
    类型: t,
    效果: b.效果,
    手术难度: b.手术难度,
    排斥概率: b.排斥概率,
    估值: b.估值,
    恢复时间: b.恢复时间,
    排斥检定: rejected,
    骰值: rejectRoll,
    判定: rejected ? '发生排斥反应' : '植入成功,无排斥',
    详情: t + '效果[' + b.效果 + '] 排斥阈值' + rejectThreshold + '% 骰值' + rejectRoll
  };
}

/* _anesthesiaRisk(patientHealth, duration) - 麻醉风险 */
function _anesthesiaRisk(patientHealth, duration) {
  var h = Number(patientHealth) || 80;
  var dur = Number(duration) || 1;
  /* 基础风险: (100-health)×0.3 + duration×1.5 */
  var base = ((100 - h) * 0.3) + (dur * 1.5);
  /* 健康低于40额外危险 */
  if (h < 40) { base += (40 - h) * 0.5; }
  /* 长时间麻醉(>6小时)陡增 */
  if (dur > 6) { base += (dur - 6) * 3; }
  if (base > 90) { base = 90; }
  if (base < 1) { base = 1; }
  var level;
  if (base < 10) { level = '极低'; }
  else if (base < 25) { level = '低'; }
  else if (base < 45) { level = '中'; }
  else if (base < 65) { level = '高'; }
  else { level = '极高'; }
  return {
    风险值: Math.round(base * 100) / 100,
    风险等级: level,
    麻醉时长: dur,
    健康基础: h,
    详情: '麻醉风险[' + level + '] 风险值' + Math.round(base * 100) / 100 + '% 时长' + dur + 'h'
  };
}

/* _surgeryRecovery(days, care) - 术后恢复 */
function _surgeryRecovery(days, care) {
  var d = Number(days) || 0;
  var c = Number(care) || 1;
  /* care: 1=无护理 2=基础护理 3=高级护理 4=专业护理 */
  var careFactor;
  if (c >= 4) { careFactor = 1.5; }
  else if (c === 3) { careFactor = 1.2; }
  else if (c === 2) { careFactor = 1.0; }
  else { careFactor = 0.6; }
  /* 每日恢复量 = 基础5 × careFactor + 医疗技能修正 */
  var dailyGain = 5 * careFactor + (pMedical * 0.3);
  var recovered = d * dailyGain;
  if (recovered > 100) { recovered = 100; }
  var completion = Math.round(recovered);
  var stage;
  if (completion < 25) { stage = '危重期'; }
  else if (completion < 50) { stage = '观察期'; }
  else if (completion < 75) { stage = '恢复期'; }
  else if (completion < 100) { stage = '康复期'; }
  else { stage = '痊愈'; }
  return {
    恢复天数: d,
    护理等级: c,
    护理系数: careFactor,
    每日恢复: Math.round(dailyGain * 100) / 100,
    累计恢复: completion,
    恢复阶段: stage,
    详情: stage + ' 累计恢复' + completion + '% 日恢复' + Math.round(dailyGain * 100) / 100 + '%'
  };
}

/* 当前主角手术状态示例 */
var sampleSurgery = _surgeryInfo('缝合');
var sampleSuccess = _surgerySuccessRate(pMedical, sampleSurgery.难度, pHealth);
var sampleFailure = _surgeryFailure(pMedical, sampleSurgery.难度);
var sampleAnesthesia = _anesthesiaRisk(pHealth, sampleSurgery.耗时);
var sampleRecovery = _surgeryRecovery(3, 2);
var sampleBionic = _bionicEffect('仿生眼');
var sampleRejection = _organRejection('肾', 5);
