  '艺术品': {继承率: 0.3, 变异范围: [-3, 3], 上限: 10, 下限: 0},
  '医疗':   {继承率: 0.4, 变异范围: [-2, 2], 上限: 8,  下限: 0},
  '研究':   {继承率: 0.5, 变异范围: [-2, 3], 上限: 10, 下限: 0},
  '采矿':   {继承率: 0.4, 变异范围: [-2, 2], 上限: 8,  下限: 0}
