    实到人数: actualAttendees,
    参与率: Math.round(ratio * 100) / 100,
    心情修正: moodAdj,
    社交影响: base.社交影响,
    耗时: base.耗时,
    银两消耗: base.银两消耗,
    关系影响: base.关系影响
  };
}

/* 墓地信息: 返回墓地详情 */
function _graveInfo(type) {
  var t = String(type) || '标准墓';
  return GRAVE_DB[t] || GRAVE_DB['浅坑'];
}

/* 解剖产出: 根据医疗技能与尸体状态计算可用产出
   产出率 = 基础产出率 / 处理难度系数
   公式以DDL骰子引擎为准,禁止本地修改 */
function _autopsyYield(skill, corpseState) {
  var skl = Number(skill) || 0;
  var state = String(corpseState) || '新鲜';
  var stateData = CORPSE_STATE_DB[state] || CORPSE_STATE_DB['新鲜'];
  var difficulty = Number(stateData.处理难度) || 1.0;
  var yields = {};
  var key;
  for (key in AUTOPSY_DB) {
    var item = AUTOPSY_DB[key];
    if (skl >= item.医疗技能要求) {
      var rate = item.产出率 / difficulty;
      yields[key] = {
        产出率: Math.round(rate * 100) / 100,
        估值: item.估值,
        用途: item.用途,
        风险: item.风险,
        产出数量: Math.round(rate * 100) / 100
      };
    }
  }
  return {
    医疗技能: skl,
    尸体状态: state,
    处理难度: difficulty,
    可用产出: yields
  };
}

/* 心情影响: 综合尸体状态与处理方式的心情修正
   公式以DDL骰子引擎为准,禁止本地修改 */
function _corpseMoodEffect(state, disposal) {
  var s = String(state) || '新鲜';
  var d = String(disposal) || '土葬';
  var stateData = CORPSE_STATE_DB[s] || CORPSE_STATE_DB['新鲜'];
  var dispData = CORPSE_DISPOSAL_DB[d] || CORPSE_DISPOSAL_DB['土葬'];
  var baseMood = Number(stateData.心情影响) || 0;
  var dispMood = Number(dispData.心情影响) || 0;
  var total = baseMood + dispMood;
  return {
    尸体状态: s,
    处理方式: d,
    状态心情: baseMood,
    处理心情: dispMood,
    总心情影响: total
  };
}

/* 疾病风险: 综合尸体状态与处理方式的疾病风险
   综合风险值 = min(100, (状态风险 + 处理风险) / 1.5)
   公式以DDL骰子引擎为准,禁止本地修改 */
function _diseaseRisk(state, disposal) {
  var s = String(state) || '新鲜';
  var d = String(disposal) || '土葬';
  var stateData = CORPSE_STATE_DB[s] || CORPSE_STATE_DB['新鲜'];
  var dispData = CORPSE_DISPOSAL_DB[d] || CORPSE_DISPOSAL_DB['土葬'];
  var stateRisk = stateData.疾病风险 || '低';
  var dispRisk = dispData.疾病风险 || '低';
  var riskMap = { '无': 0, '低': 10, '中': 30, '高': 60, '极高': 90 };
  var stateScore = riskMap[stateRisk] !== undefined ? riskMap[stateRisk] : 10;
  var dispScore = riskMap[dispRisk] !== undefined ? riskMap[dispRisk] : 10;
  var combined = Math.min(100, Math.round((stateScore + dispScore) / 1.5));
  var level;
  if (combined === 0) { level = '无'; }
  else if (combined < 20) { level = '低'; }
  else if (combined < 50) { level = '中'; }
  else if (combined < 80) { level = '高'; }
  else { level = '极高'; }
  return {
    尸体状态: s,
    处理方式: d,
    状态风险: stateRisk,
    处理风险: dispRisk,
    综合风险值: combined,
    风险等级: level
  };
}

/* 读取殖民者医疗技能与殖民地状态(MVU变量) */
