   字段: 烟雾密度加成, 毒性, 视野遮挡, 残留物 */
var FIRE_OUTPUT_DB = {
  '灰烬': { 烟雾密度加成: 1, 毒性: 0,   视野遮挡: 0.1, 残留物: '灰烬堆(可清理)' },
  '黑烟': { 烟雾密度加成: 3, 毒性: 0.3, 视野遮挡: 0.5, 残留物: '焦黑残渣' },
  '毒烟': { 烟雾密度加成: 5, 毒性: 1.0, 视野遮挡: 0.8, 残留物: '剧毒残渣(需防化)' }
};

/* 获取可燃物信息, 不存在返回木材兜底 */
function _fireMaterialInfo(type) {
  var t = String(type) || '木材';
  return FIRE_DB[t] || FIRE_DB['木材'];
}

/* 获取火势规模等级 */
function _fireSizeLevel(size) {
  var s = Number(size) || 0;
  for (var k in FIRE_SIZE_DB) {
    var range = FIRE_SIZE_DB[k].规模值范围;
    if (s >= range[0] && s <= range[1]) {
      return { 等级: k, 数据: FIRE_SIZE_DB[k] };
    }
  }
  if (s > 200) return { 等级: '烈火', 数据: FIRE_SIZE_DB['烈火'] };
  return { 等级: '微火', 数据: FIRE_SIZE_DB['微火'] };
}

/* 火势蔓延概率: fireSize × windSpeed × material系数, 使用DDL骰子引擎判定
   返回是否蔓延/蔓延规模增量/新着火点数量/检定结果 */
function _fireSpread(fireSize, windSpeed, material) {
  var size = Number(fireSize) || 0;
  var wind = Number(windSpeed) || 0;
  var mat = _fireMaterialInfo(material);
  var sizeLevel = _fireSizeLevel(size);
  var spreadRate = mat.蔓延速度 * sizeLevel.数据.蔓延修正;
  var spreadScore = size + wind * 5 * spreadRate;
  var seed = 'firespread_' + material + '_' + size + '_' + wind;
  var checkResult = _check(spreadScore, seed, '普通');
  var willSpread = checkResult.result === '普通成功' || checkResult.result === '极难成功' || checkResult.result === '大成功';
  var sizeIncrement = 0;
  var newIgnitions = 0;
  if (willSpread) {
    var bonus = 0;
    if (checkResult.result === '大成功') bonus = 0.5;
    else if (checkResult.result === '极难成功') bonus = 0.2;
    sizeIncrement = Math.round((size * 0.15 + wind * 2) * spreadRate * (1 + bonus));
    var igniteSeed = 'ignitecount_' + seed + '_' + checkResult.roll;
    var igniteRoll = _lcgRoll(igniteSeed, 1, 100)[0] / 100;
    if (mat.燃点等级 === '极低') newIgnitions = Math.floor(igniteRoll * 3) + 1;
    else if (mat.燃点等级 === '低') newIgnitions = Math.floor(igniteRoll * 2) + 1;
    else newIgnitions = Math.floor(igniteRoll * 1) + 1;
  }
  return {
    是否蔓延: willSpread,
    蔓延规模增量: sizeIncrement,
    新着火点: newIgnitions,
    蔓延系数: Math.round(spreadRate * 100) / 100,
    检定: checkResult
  };
}

/* 扑灭速度: skill×2 + 泡沫加成50, 应用扑灭难度修正
   返回每回合扑灭量/扑灭系数/是否可扑灭/检定结果 */
function _fireExtinguish(skill, tool, foamBoost) {
  var skl = Number(skill) || 0;
  var foam = foamBoost ? 50 : 0;
  var toolBonus = 0;
  var toolName = String(tool) || '徒手';
  if (toolName.indexOf('泡沫') >= 0) toolBonus = 50;
  else if (toolName.indexOf('水桶') >= 0) toolBonus = 20;
  else if (toolName.indexOf('灭火器') >= 0) toolBonus = 35;
  else if (toolName.indexOf('徒手') >= 0) toolBonus = 0;
  var score = skl * 2 + foam + toolBonus;
  var seed = 'extinguish_' + skl + '_' + toolName;
  var checkResult = _check(score, seed, '普通');
  var extMod = 1.0;
  if (checkResult.result === '大成功') extMod = 1.5;
  else if (checkResult.result === '极难成功') extMod = 1.2;
  else if (checkResult.result === '失败') extMod = 0.6;
  else if (checkResult.result === '大失败') extMod = 0.3;
  var extinguishPerTurn = Math.round(score * 0.5 * extMod);
  var minSkill = Math.max(1, Math.ceil(score / 20));
  return {
    每回合扑灭量: extinguishPerTurn,
    扑灭系数: Math.round(extMod * 100) / 100,
    是否可扑灭: checkResult.result !== '大失败',
    最小技能要求: minSkill,
    工具加成: toolBonus,
    泡沫加成: foam,
    检定: checkResult
  };
}

/* 灼伤伤害分级: 轻5HP/中15HP/重30HP/致命50HP
   返回伤害值/严重度/部位损伤描述 */
function _burnDamage(target, severity) {
  var sev = String(severity) || '轻';
  var damageTable = {
    '轻':   { 伤害: 5,  严重度: '轻度灼伤', 描述: '皮肤红肿起泡,疼痛但可恢复' },
    '中':   { 伤害: 15, 严重度: '中度灼伤', 描述: '大面积水泡,需医疗处理' },
    '重':   { 伤害: 30, 严重度: '重度灼伤', 描述: '真皮层损伤,留疤,需高级医疗' },
    '致命': { 伤害: 50, 严重度: '致命灼伤', 描述: '组织碳化,危及生命,需立即抢救' }
  };
  var dmg = damageTable[sev] || damageTable['轻'];
  var tgt = String(target) || '躯干';
  var hpField = tgt;
  if (tgt === '头部' || tgt === '躯干' || tgt === '左臂' || tgt === '右臂' || tgt === '左腿' || tgt === '右腿') {
    hpField = tgt;
  } else {
    hpField = '躯干';
  }
  var currentHp = Number(getvar('stat_data.殖民者_主角.' + hpField, {scope:'local',defaults:100})) || 100;
  var newHp = Math.max(0, currentHp - dmg.伤害);
  var scarChance = 0;
  if (sev === '中') scarChance = 0.2;
  else if (sev === '重') scarChance = 0.5;
  else if (sev === '致命') scarChance = 0.9;
  return {
    目标部位: tgt,
    伤害值: dmg.伤害,
    严重度: dmg.严重度,
    描述: dmg.描述,
    部位原HP: currentHp,
    部位新HP: newHp,
    留疤概率: scarChance
  };
}

/* 点燃判定: source(闪电/营火失控/爆炸引燃), chance为点燃概率修正
   返回是否点燃/点燃材料/初始规模/检定结果 */
function _fireIgnite(source, target, chance) {
  var src = String(source) || '闪电';
  var tgt = _fireMaterialInfo(target);
  var ch = Number(chance) || 1.0;
  if (tgt.燃点等级 === '不可燃') {
    return {
      是否点燃: false,
      点燃材料: target,
      初始规模: 0,
      不可燃原因: '材料不可燃',
      检定: null
    };
  }
  var sourceMod = 1.0;
  var baseSize = 10;
  if (src === '闪电') { sourceMod = 1.5; baseSize = 20; }
  else if (src === '营火失控') { sourceMod = 1.0; baseSize = 15; }
  else if (src === '爆炸引燃') { sourceMod = 2.0; baseSize = 40; }
  else if (src === '纵火') { sourceMod = 1.2; baseSize = 25; }
  var envTemp = Number(getvar('stat_data.殖民地.温度', {scope:'local',defaults:20})) || 20;
  var tempMod = 1.0;
  if (envTemp > 35) tempMod = 1.4;
  else if (envTemp > 25) tempMod = 1.2;
  else if (envTemp < 0) tempMod = 0.5;
  else if (envTemp < 10) tempMod = 0.8;
  var igniteScore = sourceMod * tempMod * ch * 40;
  var seed = 'ignite_' + src + '_' + target;
  var checkResult = _check(igniteScore, seed, '普通');
  var ignited = checkResult.result === '普通成功' || checkResult.result === '极难成功' || checkResult.result === '大成功';
  var initSize = 0;
  if (ignited) {
    var bonus = 0;
    if (checkResult.result === '大成功') bonus = 0.5;
    else if (checkResult.result === '极难成功') bonus = 0.2;
    initSize = Math.round(baseSize * (1 + bonus) * tempMod);
  }
  return {
    是否点燃: ignited,
    点燃材料: target,
    初始规模: initSize,
    点燃源: src,
    温度修正: Math.round(tempMod * 100) / 100,
    检定: checkResult
  };
}

/* 燃烧时长计算: material基础时长 × size规模修正
   返回总燃烧时长(小时)/规模修正/是否自然熄灭 */
function _fireDuration(material, size) {
  var mat = _fireMaterialInfo(material);
  var sz = Number(size) || 10;
  if (mat.燃点等级 === '不可燃') {
    return { 总燃烧时长: 0, 规模修正: 0, 是否自然熄灭: true, 说明: '不可燃材料' };
  }
  var sizeMod = 1.0;
  if (sz > 100) sizeMod = 1.8;
  else if (sz > 60) sizeMod = 1.5;
  else if (sz > 30) sizeMod = 1.2;
  else if (sz < 10) sizeMod = 0.7;
  var total = Math.round(Number(mat.燃烧时长) * sizeMod * 100) / 100;
  var weather = String(getvar('stat_data.殖民地.天气', {scope:'local',defaults:'晴'})) || '晴';
  var naturalExtinguish = false;
  if (weather === '大雨' || weather === '暴风雪') { total *= 0.4; naturalExtinguish = sz < 30; }
  else if (weather === '雨' || weather === '雪') { total *= 0.7; }
  total = Math.round(total * 100) / 100;
  return {
    总燃烧时长: total,
    规模修正: sizeMod,
    是否自然熄灭: naturalExtinguish,
    天气: weather
  };
}

/* 烟雾影响: density(1-10) × duration(小时), 心情-5~-20, 呼吸损伤
   返回心情惩罚/呼吸损伤/视野修正/严重度描述 */
function _smokeEffect(density, duration) {
  var dens = Number(density) || 1;
  var dur = Number(duration) || 1;
  if (dens > 10) dens = 10;
  if (dens < 1) dens = 1;
  var moodPenalty = -5;
  if (dens >= 8) moodPenalty = -20;
  else if (dens >= 6) moodPenalty = -15;
  else if (dens >= 4) moodPenalty = -10;
  var breathDamage = Math.round(dens * dur * 0.5);
  var visionMod = 1.0 - dens * 0.08;
  if (visionMod < 0.2) visionMod = 0.2;
  var severity = '轻微';
  var desc = '略有呛鼻';
  if (dens >= 8) { severity = '严重'; desc = '浓烟呛人,视野极差,呼吸损伤明显'; }
  else if (dens >= 6) { severity = '中度'; desc = '烟雾弥漫,呼吸不适'; }
  else if (dens >= 4) { severity = '轻度'; desc = '烟雾可见,略有呛鼻'; }
  return {
    烟雾密度: dens,
    持续时长: dur,
    心情惩罚: moodPenalty,
    呼吸损伤: breathDamage,
    视野修正: Math.round(visionMod * 100) / 100,
    严重度: severity,
    描述: desc
  };
}

/* 大雨灭火效果: rainLevel(1-5) × (1 - fireSize/200)
   返回每回合灭火量/是否完全扑灭/残余规模 */
function _rainExtinguish(rainLevel, fireSize) {
  var rain = Number(rainLevel) || 0;
  var size = Number(fireSize) || 0;
  if (rain <= 0) {
    return { 每回合灭火量: 0, 是否完全扑灭: false, 残余规模: size, 说明: '无雨' };
  }
  if (rain > 5) rain = 5;
  var sizeFactor = Math.max(0.1, 1 - size / 200);
  var extPerTurn = Math.round(rain * 15 * sizeFactor);
  var remaining = Math.max(0, size - extPerTurn);
  var extinguished = remaining <= 0;
  return {
    每回合灭火量: extPerTurn,
    是否完全扑灭: extinguished,
    残余规模: remaining,
    雨量等级: rain,
    说明: rain >= 4 ? '大雨有效压制火势' : '雨减缓火势'
  };
}

/* 读取殖民者建设技能与状态(MVU变量) */
var p1Name = getvar('stat_data.殖民者_主角.姓名', {scope:'local',defaults:''}) || '';
var p1Construction = Number(getvar('stat_data.殖民者_主角.建设', {scope:'local',defaults:5})) || 5;
var p1HeadHp = Number(getvar('stat_data.殖民者_主角.头部', {scope:'local',defaults:100})) || 100;
var p1TorsoHp = Number(getvar('stat_data.殖民者_主角.躯干', {scope:'local',defaults:100})) || 100;

var colonyTemp = Number(getvar('stat_data.殖民地.温度', {scope:'local',defaults:20})) || 20;
var colonyWeather = getvar('stat_data.殖民地.天气', {scope:'local',defaults:'晴'}) || '晴';
var colonyWind = Number(getvar('stat_data.殖民地.风速', {scope:'local',defaults:3})) || 3;

/* 主角火灾演示判定 */
var demoIgnite = _fireIgnite('闪电', '木材', 1.0);
var demoSpread = _fireSpread(30, colonyWind, '木材');
var demoExtinguish = _fireExtinguish(p1Construction, '泡沫灭火器', true);
var demoBurn = _burnDamage('躯干', '中');
var demoDuration = _fireDuration('木材', 30);
var demoSmoke = _smokeEffect(5, 2);
var demoRain = _rainExtinguish(3, 30);

/* 温度修正: 高温环境增加点燃概率 */
var tempRiskMod = 1.0;
if (colonyTemp > 35) { tempRiskMod = 1.4; }
else if (colonyTemp > 25) { tempRiskMod = 1.2; }
else if (colonyTemp < 0) { tempRiskMod = 0.5; }
_%>

