function _storytellerMod(storyteller, phase, seed) {
  if (storyteller === '卡桑德拉') {
    var cass = { '拓荒期': 0.3, '发展期': 0.6, '繁荣期': 1.0, '终局期': 1.8 };
    return cass[phase] || 0.3;
  }
  if (storyteller === '菲比') {
    var phoe = { '拓荒期': 0.1, '发展期': 0.3, '繁荣期': 0.6, '终局期': 1.0 };
    return phoe[phase] || 0.1;
  }
  /* 兰迪随机区间 */
  var roll = _lcgRoll(seed + '_randy', 1, 100)[0];
  var range = { '拓荒期': [0.1, 0.8], '发展期': [0.2, 1.2], '繁荣期': [0.3, 2.0], '终局期': [0.5, 3.0] };
  var r = range[phase] || range['拓荒期'];
  return Math.round((r[0] + roll / 100 * (r[1] - r[0])) * 100) / 100;
}

function _baseCooldown(storyteller, seed) {
  if (storyteller === '卡桑德拉') { return 4; }
  if (storyteller === '菲比') { return 7; }
  /* 兰迪1-10天完全不可预测 */
  return _lcgRoll(seed + '_randy_cd', 1, 10)[0];
}

function _threatPoints(wealth, stMod, gameDay) {
  var wealthPart = (Number(wealth) || 0) / 1000 * stMod;
  var timeBonus = Number(gameDay) * 0.5;
  return Math.round((wealthPart + timeBonus) * 100) / 100;
}

function _raidSize(threatPoints) {
  var t = Number(threatPoints) || 0;
  if (t <= 20) { return { tier: '微弱', headcount: '1-3人', note: '小型野兽或散兵' }; }
  if (t <= 50) { return { tier: '小型', headcount: '3-5人', note: '掠夺者小队' }; }
  if (t <= 100) { return { tier: '中型', headcount: '5-8人', note: '部族袭击' }; }
  if (t <= 200) { return { tier: '大型', headcount: '8-15人', note: '精锐佣兵团' }; }
  if (t <= 500) { return { tier: '巨型', headcount: '15-30人', note: '大型围攻' }; }
  return { tier: '终末', headcount: '30+大军', note: '全方位战争' };
}

var stMod = _storytellerMod(storyteller, phase, 'storyteller_' + gameDay);
