function _skillSum(skills) {
  var sum = 0;
  sum += Number(skills.射击) || 0;
  sum += Number(skills.格斗) || 0;
  sum += Number(skills.社交) || 0;
  sum += Number(skills.厨艺) || 0;
  sum += Number(skills.建设) || 0;
  sum += Number(skills.种植) || 0;
  sum += Number(skills.畜牧) || 0;
  sum += Number(skills.手工) || 0;
  sum += Number(skills.艺术品) || 0;
  sum += Number(skills.医疗) || 0;
  sum += Number(skills.研究) || 0;
  sum += Number(skills.采矿) || 0;
  return sum;
}

function _balanceCheck(presetA, presetB) {
  var sumA = _skillSum(presetA.技能);
  var sumB = _skillSum(presetB.技能);
  var diff = Math.abs(sumA - sumB);
  var avg = (sumA + sumB) / 2;
  var ratio = avg > 0 ? diff / avg : 1;
  return { 差值: diff, 平均: avg, 差异比: Math.round(ratio * 100) / 100, 合规: ratio <= 0.2 };
}

function _presetValid(preset) {
  var s = _skillSum(preset.技能);
  var v = Number(preset.估值) || 0;
  var tm = Number(preset.特质系数) || 0;
  var okSum = s >= 50 && s <= 120;
  var okVal = v >= 400 && v <= 1200;
  var okMod = tm >= 0.8 && tm <= 2.0;
  return { 技能总和: s, 估值: v, 系数: tm, 合法: okSum && okVal && okMod };
}

