function _surgeryDifficulty(tier) {
  var t = Number(tier) || 1;
  if (t === 1) { return '普通'; }
  if (t === 2) { return '困难'; }
  return '极难';
}

function _surgeryThreshold(medicalSkill, tier) {
  var med = Number(medicalSkill) || 0;
  var t = Number(tier) || 1;
  var base = med * 5;
  if (t === 1) { return base; }
  if (t === 2) { return Math.round(base / 2); }
  return Math.round(base / 5);
}

function _surgeryCheck(medicalSkill, tier, seed) {
  var threshold = _surgeryThreshold(medicalSkill, tier);
  var difficulty = _surgeryDifficulty(tier);
  var r = _check(threshold, seed, difficulty);
  return { 阈值: threshold, 难度: difficulty, 骰值: r.roll, 结果: r.result };
}

function _implantFailure(tier) {
  var t = Number(tier) || 1;
  if (t === 1) { return { HP损失: 20, 后果: '植入体损坏' }; }
  if (t === 2) { return { HP损失: 40, 后果: '可能致残' }; }
  if (t === 3) { return { HP损失: 60, 后果: '30%死亡' }; }
  return { HP损失: 80, 后果: '50%死亡' };
}

function _hasPowerArmorInterface(armor) {
  var a = String(armor || '');
  return a.indexOf('动力甲接口') >= 0 ? 1 : 0;
}

var p1HasInterface = _hasPowerArmorInterface(p1Armor);
